// Algorithm for determining prime numbers

begin
  var N := ReadInteger('Enter number:');
  var IsPrime := True;
  for var i := 2 to Round(Sqrt(N)) do // if number is composite, then one of its factors ≤ sqrt(N)
    if N mod i = 0 then
    begin
      IsPrime := False;
      break;
    end;
  if IsPrime then
    Println('Number', N, 'is prime') else Println('Number', N, 'is composite');
end.

// Algorithm for calculating polynomial value at point x using Horner's scheme

const n = 5;

begin
  var x := ReadReal('Enter value x:');
  Print($'Enter polynomial coefficients ({n + 1} pieces):');
  var a := ReadReal;
  var s := a;
  for var i := 1 to n do
  begin
    a := ReadReal;
    s := s * x + a;
  end;
  Println('Polynomial value at point', x, 'equals', s);
end.

