// Example of using class (static) constructor
type 
  Person = class
  private
    class arr: array of Person; // Class field. Associated not with class variable, but with class. 
    name: string;
    age: integer;
  public
    class constructor; // Class constructor. Called before creating first class object and before calling any class method
    begin
      Println('  Class constructor called');
      SetLength(arr,3);
      arr[0] := new Person('Ivanov',20);
      arr[1] := new Person('Petrova',19);
      arr[2] := new Person('Popov',35);
    end;
    constructor (n: string; a: integer);
    begin
      name := n;
      age := a;
    end;
    function ToString: string; override;
    begin
      Result := $'Name: {name}   Age: {age}';      
    end;
    class function RandomPerson: Person; // Class method. Can only access class fields
    begin
      Result := arr[Random(3)];
    end;
  end;

begin
  Println('Random persons');
  for var i:=1 to 5 do
    Println(Person.RandomPerson); // Calling class method
end.

// Method description inside class interface
// Convenience: methods can be implemented immediately after declaration
// Inconvenience: for large classes interface is hard to read
type 
  Person = class
  private
    // Class fields, as a rule, are private. Access to them - through methods and properties
    name: string;
    age: integer;
  public
    // Constructor implicitly has name Create
    constructor (n: string; a: integer);
    begin
      name := n; age := a;
    end;
    procedure Print;
    begin
      Println('Name:',name,' Age:',age);
    end;
  end;

var p,p1: Person;

begin
  p := new Person('Ivanov',20); // New constructor call syntax (recommended)
  p.Print;
  p1 := Person.Create('Popov',19); // Old constructor call syntax (not recommended)
  p1.Print;
  // Destructors are absent, instead - automatic garbage collection
end.

