// Tower of Hanoi
uses GraphABC;

type
  /// Disk type
  DiskType = record
    /// Disk diameter
    Sz: integer;
    /// Disk color
    Color: GraphABC.Color;
  end;
  /// Type of disk array on rod
  DiskArr = array of DiskType;

const
  /// Number of disks
  CountDisks = 8;
  /// Disk height
  DiskHeight = 12;
  /// Disk width increment
  DiskWidthDelta = 12;
  h = CountDisks * DiskWidthDelta * 2 + 20; 
  /// y-coordinate of disk pyramid base
  y0 = DiskHeight * CountDisks + 80;
  hh = 30;
  /// x-coordinate of first rod
  x1 = h div 2 + hh;
  /// x-coordinate of second rod
  x2 = x1 + h;
  /// x-coordinate of third rod
  x3 = x2 + h;
  /// Pause, ms
  delay = 50;

var
  /// Array of disk pyramids 
  Tower: array [1..3] of DiskArr;
  /// Array of disk counts in pyramids
  DisksInTower: array [1..3] of integer;
  /// Move number
  MoveNumber: integer;

/// Drawing pyramid
procedure DrawTower(a: DiskArr; n: integer; x0,y0: integer);
begin
  Brush.Color := clBlack;
  Rectangle(x0-5,y0,x0+5,y0-DiskHeight*CountDisks-10);
  for var i:=0 to n-1 do
  begin
    Brush.Color := a[i].Color;
    Rectangle(x0-a[i].sz*DiskWidthDelta,y0-DiskHeight*(i-1),x0+a[i].sz*DiskWidthDelta,y0-DiskHeight*i+1)
  end;
end;

/// Drawing all pyramids and info string
procedure DrawAll;
begin
  DrawTower(Tower[1],DisksInTower[1],x1,y0);
  DrawTower(Tower[2],DisksInTower[2],x2,y0);
  DrawTower(Tower[3],DisksInTower[3],x3,y0);
  Brush.Color := clWhite;
  TextOut(20,20,'Number of disk moves = '+MoveNumber);
  Redraw;
end;

/// Moving disk from rod FromN to rod ToN
procedure MoveDisk(FromN, ToN: integer);
begin
  Inc(MoveNumber);
  Inc(DisksInTower[ToN]);
  Tower[ToN][DisksInTower[ToN]-1] := Tower[FromN][DisksInTower[FromN]-1];
  Dec(DisksInTower[FromN]);
  Sleep(delay);
  ClearWindow;
  DrawAll;
end;

/// Main recursive procedure of "Tower of Hanoi" algorithm
procedure MoveTower(n: integer; FromN, ToN, WorkN: integer);
begin
  if n=0 then exit;
  MoveTower(n-1, FromN, WorkN, ToN);
  MoveDisk(FromN, ToN);
  MoveTower(n-1, WorkN, ToN, FromN);
end;

