procedure TestApproxCheb(s:string; a,b:array of real; eps:real);
// a - array of computed values
// b - array of expected values
// eps - allowable absolute error of solutions
begin
  for var i:=0 to a.Length-1 do begin
    var Msg:=s+': found: '+a[i]+', expected '+b[i];
    Assert(Abs(Abs(a[i])-Abs(b[i]))<=eps,Msg);
    end
end;

procedure TestDecomp(s:string; a:array[,] of real; b:array of real;
    roots:array of real; eps:real);
// a - system matrix;
// b - right-hand side vector;
// roots - vector of reference solutions;
// eps - maximum absolute error of solutions
begin
  var oD:=new Decomp(a);
  var Msg:=s+': cond='+oD.cond+' matrix singularity detected';
  var Flag:=oD.cond+1=oD.cond;
  Assert(not Flag,Msg);
  if not Flag then begin
    oD.Solve(b);
    var sum:=b.Zip(roots,(p,q)->Abs(Abs(p)-Abs(q))).Sum;
    Msg:=s+': unacceptable error '+sum+' > '+eps+NewLine+
        'Received : '+b.JoinIntoString(' ')+NewLine+
        'Expected: '+roots.JoinIntoString(' ');
    Assert(sum<=eps,Msg);
    end
end;

procedure TestFactors(s:string; a:array of integer; roots:array of integer);
// a - polynomial coefficients;
// aroots - vector of reference solutions;
begin
  var oL:=new Factors(a);
  var r:=oL.Factorize;
  var r1:=r.Rows.SelectMany(x->x);
  var Msg:=s+': error.'+Newline+r1.JoinIntoString+': received'+NewLine+
      roots.JoinIntoString+': expected';
  if r1.Count=roots.Count then begin
    var s1:=r1.Zip(roots,(i,j)->i-j).Sum;
    Assert(s1=0,Msg)
    end
  else
    Assert(false,Msg)
end;

procedure TestFMin(s:string; f:real->real; a,b,etx,ety,epsx,epsy:real);
// etx - expected argument value
// etx - expected function value
// epsx - allowable absolute error for argument
// epsy - allowable absolute error for function
begin
  var oL:=new FMin(f,a,b);
  var (x,y):=(oL.x,oL.Value);
  var Msg:=s+': found argument: '+x+', expected '+etx;
  Assert(Abs(x-etx)<=epsx,Msg);
  Msg:=s+': function value: '+y+', expected '+ety;
  Assert(Abs(y-ety)<=epsy,Msg);
end;

procedure TestFMinN1(s:string; f:function(x:array of real):real;
    xb:array of real; etx:array of real; ety,epsx,epsy:real);
// xb - array of arguments
// etx - array of expected argument values
// etx - expected function value
// epsx - allowable absolute error for argument
// epsy - allowable absolute error for function
begin
  var oL:=new FMinN(xb,f);
  var x:=oL.HJ;
  var y:=f(x);
  var Msg:=s+':'+NewLine+'found arguments  : '+
      x.Select(t->Format('{0}',t)).JoinIntoString+NewLine+
      'expected arguments: '+
      etx.Select(t->Format('{0}',t)).JoinIntoString;
  for var i:=0 to x.Length-1 do
    if Abs(x[i]-etx[i])>epsx then begin
      Assert(false,Msg);
      break
    end;
  Msg:=s+': function value: '+y+', expected '+ety;
  Assert(Abs(y-ety)<=epsy,Msg);
end;

