      a+', expected value '+r;
  Assert(Abs(a-r)<=eps,Msg)
end;

procedure TestMatrixV(s:string; a,r:Vector; eps:real);
// a - vector of found values;
// r - vector of expected values;
// eps - maximum allowable absolute error
begin
