    Assert(Abs(a.Value[i]-r.Value[i])<=eps,
        s+': error exceeds allowable.'+Newline+'Received value '+
        a.Value[i]+', expected value '+r.Value[i])
end;

procedure TestMatrixM(s:string; a,r:Matrix; eps:real);
// a - computed matrix;
// r - reference matrix;
// eps - maximum allowable absolute error
begin
  for var i:=0 to a.RowCount-1 do
    for var j:=0 to a.ColCount-1 do
      Assert(Abs(a.Value[i,j]-r.Value[i,j])<=eps,
          s+': error exceeds allowable.'+Newline+'Received value a['+
          i+','+j+']='+a.Value[i,j]+', expected value '+r.Value[i,j])
end;

procedure TestPolRt(s:string; a:Polynom; roots:array of complex; eps:real);
// roots - array of expected root values
// eps - maximum absolute error of solutions
begin
  var oP:=new PolRt(a);
  if oP.ier>0 then begin
    var Msg:=s+': test failed, error with code '+oP.ier;
    Assert(false,Msg)
    end
  else begin
    var r:=oP.Value;
    for var i:=0 to r.Length-1 do begin
      var Msg:=s+': found: ('+r[i].Real+','+r[i].Imaginary+'), expected ('+
        roots[i].Real+','+roots[i].Imaginary+')';
      Assert(Complex.Abs(r[i]-roots[i])<=eps,Msg);
      end
    end  
end;

procedure TestPolynomD(s:string; res,lim:real; n1,n2:integer);
// res - computed value
// lim - maximum allowable value for res
// also checks condition n2<n1
begin
