// eps - allowable absolute error of solution
begin
  var Msg:string;
  var oQ:=new Quanc8(f,a,b,ae,re);
  var r1:=oQ.Value;
  if r1[2]=0 then begin
    Msg:=s+': computed '+r1[0]+', expected '+r2;
