procedure TestRootsIsolation(s:string; f:real->real; a,b,h:real;
    t:array of real);
// f - function
// a,b - search interval boundaries
// h - search step
// t - reference array of function zeros
begin
  var oRI:=new RootsIsolation(f,a,b,h);
  var r:=oRI.Value;
  for var i:=0 to t.Length-1 do begin
    var Msg:=s+': zero point '+t[i]+' not in interval ['+r[i][0]+';'+r[i][1]+']';
