// Using references instead of pointers for creating singly linked list
// We recommend this approach
type 
  Node = class
    data: integer;
    next: Node;
    constructor (d: integer; n: Node);
    begin
      data := d;
      next := n;
    end;
  end;

begin
  // Variable of type "class" represents a reference to object allocated by constructor
  var first: Node := nil;
  // Add to beginning of singly linked list
  first := new Node(3,first);
  first := new Node(7,first);
  first := new Node(5,first);

  // Output singly linked list. ^ are absent
  Println('Contents of singly linked list (using references instead of pointers):');
  var p := first;
  while p<>nil do
  begin
    Print(p.data);
    p := p.next;
  end;

  // Destruction of singly linked list
  first := nil; // Garbage collector will collect memory that no one points to anymore
end.

// Dynamic memory allocation
// Using pointers for creating singly linked list
type 
  PNode = ^TNode;
  TNode = record
    data: integer;
    next: PNode;
  end;

function NewNode(d: integer; n: PNode): PNode;
begin
  New(Result);
  Result^.data := d;
  Result^.next := n;
end;

begin
  var first: PNode := nil;

  // Add to beginning of singly linked list
  first := NewNode(3,first);
  first := NewNode(7,first);
  first := NewNode(5,first);

  // Output singly linked list
  Println('Contents of singly linked list:');
  var p := first;
  while p<>nil do
  begin
    Print(p^.data);
    p := p^.next;
  end;

  // Destruction of singly linked list
  p := first;
  while p<>nil do
  begin
    var p1 := p;
    p := p^.next;
    Dispose(p1); // Memory must be returned
  end;
end.

