procedure Perm(a: array of integer; m: integer);
begin
  if m=1 then
    a.Println;
  for var i:=0 to m-1 do
  begin
    Swap(a[i],a[m-1]);
    Perm(a,m-1);
    Swap(a[i],a[m-1]);
  end;  
end;

