// Boxing-unboxing of value types
var 
  i: integer := 2;
  r: real := 3.14;
  o: object;

begin
  o := i; // Boxing: object of value type integer is boxed into object of reference type, 
          // which is assigned to variable o
          // Type conversion during boxing - implicit
  Println(integer(o)); // Unboxing: value is extracted from boxed object        
                       // Type conversion during unboxing - explicit
  o := r;
  Println(real(o));

  try // When type conversion is incorrect, InvalidCastException is generated
    Println(shortint(o));
  except
    on e: Exception do
      Println(e.GetType);
  end;
end.

