function CalcIntegral(a,b: real; N: integer; f: Fun): real;
begin
  Result := 0;
  var x := a;
  var h := (b-a)/N;
  for var i:=0 to N-1 do
  begin
    Result += f(x);
    x += h;
  end;
  Result *= h;
end;

