  a.Println;
  var b := QS(a);
  b.Println;
end.

function QuickSort(a: sequence of integer): sequence of integer;
begin
  if a.Count = 0 then
    Result := a
  else 
  begin
    var head := a.First();
    var tail := a.Skip(1);
    Result := QuickSort(tail.Where(x->x<=head)) + 
              head + 
              QuickSort(tail.Where(x->x>head));
  end;
end; 

begin
  var a := ArrRandom(20);
  a.Println;
  QuickSort(a).Println;
end.

function IsSafe(board: array of integer; row, col: integer): boolean;
begin
  Result := True;
  for var i := 0 to row - 1 do
    if (board[i] = col) or
       (board[i] - i = col - row) or
       (board[i] + i = col + row) then
    begin
      Result := False;
      exit; 
    end;
end;

procedure SolveNQueens(board: array of integer; row: integer);
begin
  if row = 8 then
    board.Println
  else
    for var col := 0 to 7 do
      if IsSafe(board, row, col) then
      begin
        board[row] := col;
        SolveNQueens(board, row + 1);
      end;
end;

begin
  var board := [0] * 8; 
  SolveNQueens(board, 0);
end.

