procedure FillByRandom(a: array of integer; minValue, maxValue: integer);
begin
  for var i := 0 to a.Length - 1 do
    a[i] := PABCSystem.Random(minValue, maxValue);
end;

procedure FillByValue<T>(a: array of T; x: T);
begin
  for var i := 0 to a.Length - 1 do
    a[i] := x;
end;

function CreateRandomIntegerArray(n: integer; minValue, maxValue: integer): array of integer;
begin
  SetLength(Result, n);
  FillByRandom(Result, minValue, maxValue);
end;

function CreateRandomRealArray(n: integer; minValue, maxValue: real): array of real;
begin
  SetLength(Result, n);
  FillByRandom(Result, minValue, maxValue);
end;

procedure ReadArray(a: array of integer);
begin
  for var i := 0 to a.Length - 1 do
    read(a[i]);
  readln;  
end;

procedure WriteArray<T>(a: array of T; delimiter: string := ' ');
begin
  if (a=nil) or (a.Length=0) then
    exit;
  for var i := 0 to a.Length - 2 do
    write(a[i], delimiter);
  write(a[a.Length - 1]);  
end;

procedure WritelnArray<T>(a: array of T; delimiter: string := ' ');
begin
  WriteArray(a, delimiter);
  writeln;
end;

procedure Sort<T>(a: array of T);
begin
  System.Array.Sort(a);
end;

procedure SortDescending<T>(a: array of T);
begin
  System.Array.Sort(a);
  System.Array.Reverse(a);
end;

procedure FillByRandom(a: array [,] of integer; minValue, maxValue: integer);
begin
  for var i := 0 to a.GetLength(0) - 1 do
    for var j := 0 to a.GetLength(1) - 1 do
      a[i, j] := PABCSystem.Random(minValue, maxValue);
end;

procedure FillByValue<T>(a: array [,] of T; x: T);
begin
  for var i := 0 to a.GetLength(0) - 1 do
    for var j := 0 to a.GetLength(1) - 1 do
      a[i, j] := x
end;

function CreateRandomIntegerMatrix(m, n: integer; minValue, maxValue: integer): array [,] of integer;
begin
  SetLength(Result, m, n);  
  FillByRandom(Result, minValue, maxValue);
end;

function CreateRandomRealMatrix(m, n: integer; minValue, maxValue: real): array [,] of real;
begin
  SetLength(Result, m, n);  
  FillByRandom(Result, minValue, maxValue);
end;

procedure WriteMatrix<T>(a: array [,] of T; width: integer := 0);
begin
  for var i := 0 to a.GetLength(0) - 1 do
  begin
    for var j := 0 to a.GetLength(1) - 1 do
      write(a[i, j]:width, ' ');
    writeln;  
  end;
end;

procedure WriteMatrix(a: array [,] of real; width: integer := 0; digitsafterpoint: integer := 2);
begin
  for var i := 0 to a.GetLength(0) - 1 do
  begin
    for var j := 0 to a.GetLength(1) - 1 do
      write(a[i, j]:width:digitsafterpoint, ' ');
    writeln;  
  end;
end;

procedure &Array.Write(delimiter: string);
begin
  if Self.Rank = 1 then
    for var i := 0 to Self.Length - 1 do
    begin
      PABCSystem.write(Self.GetValue(i));
      if i < Self.Length - 1 then
        PABCSystem.write(delimiter);
    end
  else if Self.Rank = 2 then 
    for var i := 0 to Self.GetLength(0) - 1 do
    begin
      for var j := 0 to Self.GetLength(1) - 1 do
        PABCSystem.write(Self.GetValue(i, j), delimiter);
      PABCSystem.writeln;
    end;
end;

procedure &Array.Writeln(delimiter: string);
begin
  Self.Write(delimiter);
  PABCSystem.writeln;
end;

type
  SingleNode<T> = class
  private 
    fData: T;
    fNext: SingleNode<T>;
  public 
    constructor Create(pData: T; pNext: SingleNode<T>);
    begin
      fData := pData;
      fNext := pNext;
    end;

    property Data: T read fData write fData;
    property Next: SingleNode<T> read fNext write fNext;
  end;

type
  Stack<T> = class
  private 
    fTop: SingleNode<T> := nil; 
  public 
    constructor Create;
    begin
      fTop := nil;
    end;

    procedure Push(x: T);
    begin
      fTop := new SingleNode<T>(x, fTop);
    end;

    function Pop: T;
    begin
      if IsEmpty then 
        raise new Exception('Attempt to pop element from empty stack');

      Result := fTop.data;
      fTop := fTop.next;  
    end;

    function Top: T;
    begin
      if IsEmpty then 
        raise new Exception('Attempt to get element from empty stack');

      Result := fTop.data;
    end;

    function IsEmpty: boolean;
    begin
      Result := (fTop = nil);
    end;

    function ToString: string; override;
    begin
      Result := '';
      var curElem := fTop;
      while curElem <> nil do
      begin
        Result += curElem.data.ToString + ' ';
        curElem := curElem.next;
      end;
    end;

    procedure Print;
    begin
      write(ToString);
    end;

    procedure Println;
    begin
      writeln(ToString);
    end;
  end;

type
  Queue<T> = class
  private 
    head: SingleNode<T>;
    tail: SingleNode<T>;
  public 
    constructor Create;
    begin
      head := nil;
      tail := nil;
    end;

    procedure Enqueue(x: T);
    begin
      if IsEmpty then
      begin
        head := new SingleNode<T>(x, nil);
        tail := head;
      end
      else
      begin
        tail.next := new SingleNode<T>(x, nil);
        tail := tail.next;
      end;
    end;

    function Dequeue: T;
    begin
      if IsEmpty then 
        raise new Exception('Attempt to remove element from empty queue');

      Result := head.data;
      head := head.next;
      if head = nil then
        tail := nil;
    end;

    function Top: T;
    begin
      if IsEmpty then 
        raise new Exception('Attempt to get element from empty queue');
      Result := head.data;
    end;

    function IsEmpty: boolean;
    begin
      Result := (head = nil);
      if Result then
        Assert(tail = nil);
    end;

    function ToString: string; override;
    begin
      Result := '';
      var curElem := head;
      while curElem <> nil do
      begin
        Result += curElem.data + ' ';
        curElem := curElem.next;
      end;
    end;

    procedure Print;
    begin
      write(ToString);
    end;

    procedure Println;
    begin
      writeln(ToString);
    end;
  end;

type
  DynArray<T> = class
  private 
    fData: array of T;
    fSize: integer;
    fCap: integer;

    procedure SetElem(index: integer; x: T);
    begin
      if (index < 0) or (index > fSize - 1) then 
        raise new Exception('Attempt to set value to element outside array bounds with index ' + index.ToString);

      fData[index] := x;
    end;

    function GetElem(index: integer): T;
    begin
      if (index < 0) or (index > fSize - 1) then 
        raise new Exception('Attempt to get value from element outside array bounds with index ' + index.ToString);

      Result := fData[index];
    end;

  public 
    constructor Create;
    begin
      Create(0);
    end;

    constructor Create(pSize: integer);
    begin
      if pSize < 0 then
        raise new Exception('Attempt to set negative value to array size ' + pSize.ToString);

      fSize := pSize;
      fCap := 2 * pSize + 4;
      SetLength(fData, fCap);
    end;

    procedure Reserve(newCap: integer);
    begin
      if newCap > fCap then 
      begin
        SetLength(fData, newCap);
        fCap := newCap;
      end;
    end;

    procedure Resize(newSize: integer);
    begin
      if newSize < 0 then
        raise new Exception('Attempt to set negative value to array size ' + newSize.ToString);

      if newSize > fCap then
      begin
        Reserve(2 * newSize);
        for var i := fSize to newSize - 1 do
          fData[i] := default(T);
      end;
      fSize := newSize;
    end;

    procedure Add(x: T);
    begin
      Resize(fSize + 1);
      fData[fSize - 1] := x;
    end;

    procedure Insert(pos: integer; x: T);
    begin
      if (pos < 0) or (pos > fSize - 1) then 
        raise new Exception('Attempt to insert outside array bounds at position ' + pos.ToString);

      Resize(fSize + 1);
      for var i := fSize - 2 downto pos do
        fData[i + 1] := fData[i];
      fData[pos] := x;
    end;

    procedure Remove(pos: integer);
    begin
      if (pos < 0) or (pos > fSize - 1) then 
        raise new Exception('Attempt to remove outside array bounds from position ' + pos.ToString);

      for var i := pos to fSize - 2 do
        fData[i] := fData[i + 1];
      Resize(fSize - 1);
    end;

    function Find(x: T): integer;
    begin
      Result := -1;
      for var i := 0 to fSize - 1 do
        if fData[i] = x then
        begin
          Result := i;
          exit;
        end;
    end;

    property Count: integer read fSize write Resize;
    property Capacity: integer read fCap write Reserve;
    property Elem[index: integer]: T read GetElem write SetElem; default;

    function ToString: string; override;
    begin
      Result := '';
      for var i := 0 to fSize - 1 do
        Result += fData[i].ToString + ' '; 
    end;

    procedure Print;
    begin
      write(ToString);
    end;

    procedure Println;
    begin
      writeln(ToString);
    end;
  end;

