function Cartesian<T>(Self: array of T; n: integer): sequence of array of T; extensionmethod;
begin
  var r := new integer[n];
  var ar1 := new T[n];
  for var i:=0 to n-1 do
    ar1[i] := Self[r[i]];
  yield ar1;

  var m := Self.Length;
  while True do
  begin
    var i := n-1;  
    r[i] += 1;
    while r[i]>=m do
    begin
      r[i] := 0;
      i -= 1;
      if i<0 then
        exit;
      r[i] += 1;
    end;

    var ar := new T[n];
    for var j:=0 to n-1 do
      ar[j] := Self[r[j]];
    yield ar;
  end;  
end;

