    if counts.ContainsKey(ch) then
      counts[ch] += 1
    else
      counts[ch] := 1;
  foreach var ch in t do
    if counts.ContainsKey(ch) then
    begin
      counts[ch] -= 1;
      if counts[ch] = 0 then
        counts.Remove(ch);
