procedure Build(const lists: array of array of integer; index: integer; current: List<integer>; resultList : List<array of integer>);
begin
  if index = lists.Length then
  begin
    resultList.Add(current.ToArray);
    exit;
  end;
  foreach var value in lists[index] do
  begin
    current.Add(value);
    Build(lists, index + 1, current, resultList);
    current.RemoveAt(current.Count - 1);
  end;
end;

