function Staircases(n: integer): integer;
begin
  if (n = 0) or (n = 1) then
    exit(1);
  if n = 2 then
    exit(2);
  var dp := new integer[n + 1];
  dp[0] := 1;
  dp[1] := 1;
  dp[2] := 2;
  for var i := 3 to n do
    dp[i] := dp[i - 1] + dp[i - 2] + dp[i - 3];
  Result := dp[n];
end;

