function WordAbbr(const word: string): string;
begin
  if word.Length < 3 then
    exit(word);
  Result := word[1] + (word.Length - 2).ToString + word[word.Length];
end;

function IsUniqueWordAbbreviation(const dictionary: array of string; const word: string): boolean;
begin
  var groups := new Dictionary<string, List<string>>;
  foreach var entry in dictionary do
  begin
    var abbr := WordAbbr(entry);
    if not groups.ContainsKey(abbr) then
      groups[abbr] := new List<string>;
    groups[abbr].Add(entry);
  end;
  var target := WordAbbr(word);
  if not groups.ContainsKey(target) then
    exit(True);
  var matches := groups[target];
  Result := (matches.Count = 1) and (matches[0] = word);
end;

