function MinConsecutiveSum(const nums: array of integer; target: integer): integer;
begin
  var n := nums.Length;
  var minLen := integer.MaxValue;
  var currentSum := 0;
  var left := 0;
  for var right := 0 to n - 1 do
  begin
    currentSum += nums[right];
    while currentSum >= target do
    begin
      minLen := Min(minLen, right - left + 1);
      currentSum -= nums[left];
      left += 1;
    end;
  end;
  if minLen = integer.MaxValue then
    Result := 0
  else
    Result := minLen;
end;

