  dp[0] := 1;
  dp[1] := 1;
  for var i := 2 to s.Length do
  begin
    if s[i] <> '0' then
      dp[i] := dp[i] + dp[i - 1];
    var twoDigit := (Ord(s[i - 1]) - Ord('0')) * 10 + (Ord(s[i]) - Ord('0'));
    if (twoDigit >= 10) and (twoDigit <= 26) then
      dp[i] := dp[i] + dp[i - 2];
  end;
  Result := dp[s.Length];
end;

