type
  Matrix2 = array[,] of int64;

procedure Multiply(var F: Matrix2; const M: Matrix2);
begin
  var x := F[0,0] * M[0,0] + F[0,1] * M[1,0];
  var y := F[0,0] * M[0,1] + F[0,1] * M[1,1];
  var z := F[1,0] * M[0,0] + F[1,1] * M[1,0];
  var w := F[1,0] * M[0,1] + F[1,1] * M[1,1];
  F[0,0] := x;
  F[0,1] := y;
  F[1,0] := z;
  F[1,1] := w;
end;

procedure Power(var F: Matrix2; n: integer);
begin
  if (n = 0) or (n = 1) then
    exit;
  Power(F, n div 2);
  Multiply(F, F);
  if n mod 2 <> 0 then
  begin
    var M := new int64[2, 2];

    M[0,0] := 1; M[0,1] := 1;
    M[1,0] := 1; M[1,1] := 0;
    Multiply(F, M);
  end;
end;

