  foreach var interval in intervals do
    allIntervals.Add(Copy(interval));
  allIntervals.Add(Copy(newInterval));
  allIntervals.Sort((a, b) -> a[0].CompareTo(b[0]));
  var merged := new List<array of integer>;
  foreach var interval in allIntervals do
    if (merged.Count = 0) or (merged[merged.Count - 1][1] < interval[0]) then
      merged.Add(Copy(interval))
    else
    begin
      var last := merged[merged.Count - 1];
      if interval[1] > last[1] then
      begin
        last[1] := interval[1];
        merged[merged.Count - 1] := last;
      end;
    end;
  Result := merged.ToArray;
end;

