  if arr.Length = 2 then begin Result := Max(arr[0], arr[1]); exit; end;
  var dp := new integer[arr.Length];
  dp[0] := arr[0];
  dp[1] := Max(arr[0], arr[1]);
  for var i := 2 to arr.Length - 1 do
    dp[i] := Max(dp[i-1], dp[i-2] + arr[i]);
  Result := dp[arr.Length - 1];
end;

function IsPossibleTarget(target: array of integer): boolean;
begin
  // Use a max-heap simulation using SortedDictionary of counts (since no built-in heap)
  var total := 0;
  foreach var v in target do total += v;
  var dict := new Dictionary<integer, integer>;
  foreach var v in target do
    if dict.ContainsKey(v) then dict[v] += 1 else dict[v] := 1;
  while True do
  begin
    // get current max
    var num := dict.Keys.Max;
    // remove one occurrence
    dict[num] -= 1;
    if dict[num] = 0 then dict.Remove(num);
    total -= num;
    if num = 1 then begin Result := True; exit; end;
    if (total = 1) then begin Result := True; exit; end;
    if (num < total) or (total = 0) or (num mod total = 0) then begin Result := False; exit; end;
    var newnum := num mod total;
    if dict.ContainsKey(newnum) then dict[newnum] += 1 else dict[newnum] := 1;
    total += newnum;
  end;
end;

function IsAnagram(s, t: string): boolean;
begin
  if s.Length <> t.Length then
    exit(False);
  // Sort and compare
  var sa := s.ToCharArray; sa.Sort;
  var ta := t.ToCharArray; ta.Sort;
  Result := new string(sa) = new string(ta);
end;

function ListIntersection(nums1, nums2: array of integer): array of integer;
begin
  var counter1 := new Dictionary<integer, integer>;
  var counter2 := new Dictionary<integer, integer>;
  foreach var num in nums1 do
    if counter1.ContainsKey(num) then counter1[num] += 1 else counter1[num] := 1;
  foreach var num in nums2 do
    if counter2.ContainsKey(num) then counter2[num] += 1 else counter2[num] := 1;
  var res := new List<integer>;
  foreach var key in counter1.Keys do
    if counter2.ContainsKey(key) then
      for var i := 1 to Min(counter1[key], counter2[key]) do
        res.Add(key);
  Result := res.ToArray;
end;

function MaxSumNonadjacent(nums: array of integer): integer;
begin
  if nums = nil then exit(0);
  var incl := 0;
  var excl := 0;
  foreach var i in nums do
  begin
    var new_excl := Max(excl, incl);
    incl := excl + i;
    excl := new_excl;
  end;
  Result := Max(incl, excl);
end;

function IsSquareSum(c: integer): boolean;
begin
  if c < 0 then begin Result := False; exit; end;
  var limit := Trunc(Sqrt(c));
  for var i := 0 to limit do
  begin
    var remain := c - i * i;
    var r := Trunc(Sqrt(remain));
    if r * r = remain then begin Result := True; exit; end;
  end;
  Result := False;
end;

function ToTitleCase(s: string): string;
begin
  var parts := s.Split(' ');
  for var i := 0 to parts.Length - 1 do
    if parts[i].Length > 0 then
      parts[i] := parts[i][0].ToUpper + parts[i].Substring(1);
  Result := String.Join(' ', parts);
end;

function Partitions(n: integer): integer;
begin
  var p := new integer[n + 1];
  for var i := 0 to n do p[i] := 0;
  p[0] := 1;
  for var k := 1 to n do
    for var i := k to n do
      p[i] += p[i - k];
  Result := p[n];
end;

function QuickSelect(arr: array of integer; k: integer): integer;
begin
  // Implement simple QuickSelect using iterative partitioning
  var a := arr.Clone() as array of integer;
  var left := 0; var right := a.Length - 1;
  while True do
  begin
    var pivot := a[(left + right) div 2];
    var i := left; var j := right;
    while i <= j do
    begin
      while a[i] < pivot do i += 1;
      while a[j] > pivot do j -= 1;
      if i <= j then
      begin
        var tmp := a[i]; a[i] := a[j]; a[j] := tmp;
        i += 1; j -= 1;
      end;
    end;
    if k - 1 <= j then right := j
    else if k - 1 >= i then left := i
    else begin Result := a[k - 1]; exit; end;
  end;
end;

function NearestSmallerLeft(arr: array of integer): array of integer;
begin
  var st := new List<integer>;
  var res := new List<integer>;
  foreach var x in arr do
  begin
    while (st.Count > 0) and (st[st.Count - 1] >= x) do
      st.RemoveAt(st.Count - 1);
    if st.Count = 0 then res.Add(-1) else res.Add(st[st.Count - 1]);
    st.Add(x);
  end;
  Result := res.ToArray;
end;

function CarRace(initial_positions, speeds: array of integer; time: integer): array of integer;
begin
  var positions := new integer[initial_positions.Length];
  for var i := 0 to initial_positions.Length - 1 do
    positions[i] := initial_positions[i] + speeds[i] * time;
  Result := positions;
end;

function MinMovesToUnique(A: array of integer): integer;
begin
  // Approach: count frequencies, then greedily assign
  var MAX := 100000; // a cap similar to original implementation; adjust as needed
  var counts := new Dictionary<integer, integer>;
  foreach var x in A do
    if counts.ContainsKey(x) then counts[x] += 1 else counts[x] := 1;
  var taken := new Queue<integer>;
  var ans := 0;
  for var i := 0 to MAX - 1 do
  begin
    if counts.ContainsKey(i) and (counts[i] > 1) then
      for var t := 1 to counts[i] - 1 do
        taken.Enqueue(i)
    else if (taken.Count > 0) and (not counts.ContainsKey(i) or (counts[i] = 0)) then
    begin
      ans += i - taken.Dequeue;
    end;
  end;
  Result := ans;
end;

function Equilibrium(arr: array of integer): integer;
begin
  var total_sum := 0;
  foreach var v in arr do total_sum += v;
  var left_sum := 0;
  for var i := 0 to arr.Length - 1 do
  begin
    total_sum -= arr[i];
    if left_sum = total_sum then begin Result := i; exit; end;
    left_sum += arr[i];
  end;
  Result := -1;
end;

function LongestCommonPrefix(words: array of string): string;
begin
  if (words = nil) or (words.Length = 0) then
  begin
    Result := '';
    exit;
  end;

  var pref := words[0];
  for var i := 1 to words.Length - 1 do
  begin
    while (pref.Length > 0) and (not words[i].StartsWith(pref)) do
      pref := pref.Substring(0, pref.Length - 1);
    if pref.Length = 0 then break;
  end;

  Result := pref;
end;

function CountPalSub(s: string): integer;
begin
  var cnt := 0;
  // expand-around-center without local functions
  for var center := 0 to s.Length - 1 do
  begin
    // odd-length
    var l := center;
    var r := center;
    while (l >= 0) and (r < s.Length) and (s[l] = s[r]) do
    begin
      cnt += 1;
      l -= 1;
      r += 1;
    end;

    // even-length
    l := center;
    r := center + 1;
    while (l >= 0) and (r < s.Length) and (s[l] = s[r]) do
    begin
      cnt += 1;
      l -= 1;
      r += 1;
    end;
  end;

  Result := cnt;
end;

function RotateRight(a: array of integer; k: integer): array of integer;
begin
  var n := a.Length;
  if n = 0 then
  begin
    Result := a;
    exit;
  end;

  var shift := k mod n;
  var outArr := new integer[n];
  for var i := 0 to n - 1 do
    outArr[(i + shift) mod n] := a[i];

  Result := outArr;
end;

function OneEdit(a, b: string): boolean;
begin
  var la := a.Length;
  var lb := b.Length;

  if Abs(la - lb) > 1 then
  begin
    Result := False;
    exit;
  end;

  var i := 0;
  var j := 0;
  var diff := 0;

  while (i < la) and (j < lb) do
  begin
    if a[i] = b[j] then
    begin
      i += 1;
      j += 1;
    end
    else
    begin
      diff += 1;
      if diff > 1 then
      begin
        Result := False;
        exit;
      end;

      if la > lb then i += 1
      else if lb > la then j += 1
      else begin i += 1; j += 1; end;
    end;
  end;

  diff += (la - i) + (lb - j);

  Result := diff = 1;
end;

function IsToeplitz(mtx: array of array of integer): boolean;
begin
  var rows := mtx.Length;
  var cols := mtx[0].Length;

  for var r := 1 to rows - 1 do
    for var c := 1 to cols - 1 do
      if mtx[r][c] <> mtx[r - 1][c - 1] then
      begin
        Result := False;
        exit;
      end;

  Result := True;
end;

function AllSubsets(a: array of integer): array of array of integer;
begin
  var n := a.Length;
  var total := 1 shl n;
  var res := new List<array of integer>;

  for var mask := 0 to total - 1 do
  begin
    var temp := new List<integer>;
    for var bit := 0 to n - 1 do
      if ((mask shr bit) and 1) = 1 then
        temp.Add(a[bit]);
    res.Add(temp.ToArray);
  end;

  Result := res.ToArray;
end;

function DigitalRoot(x: integer): integer;
begin
  if x = 0 then
  begin
    Result := 0;
    exit;
  end;
  Result := 1 + (x - 1) mod 9;
end;

function BalancedBrackets(s: string): boolean;
begin
  var st := new List<char>;

  foreach var ch in s do
  begin
    if (ch = '(') or (ch = '[') or (ch = '{') then
      st.Add(ch)
    else if (ch = ')') or (ch = ']') or (ch = '}') then
    begin
      if st.Count = 0 then
      begin
        Result := False;
        exit;
      end;

      var top := st[st.Count - 1];
      st.RemoveAt(st.Count - 1);

      if (ch = ')') and (top <> '(') then begin Result := False; exit; end;
      if (ch = ']') and (top <> '[') then begin Result := False; exit; end;
      if (ch = '}') and (top <> '{') then begin Result := False; exit; end;
    end;
  end;

  Result := st.Count = 0;
end;

function TrailingZeros(n: integer): integer;
begin
  var countZeros := 0;
  var t := n;
  while t > 0 do
  begin
    t := t div 5;
    countZeros += t;
  end;
  Result := countZeros;
end;

function MergeSorted(a, b: array of integer): array of integer;
begin
  var i := 0;
  var j := 0;
  var merged := new List<integer>;

  while (i < a.Length) and (j < b.Length) do
  begin
    if a[i] < b[j] then
    begin
      merged.Add(a[i]);
      i += 1;
    end
    else
    begin
      merged.Add(b[j]);
      j += 1;
    end;
  end;

  while i < a.Length do
  begin
    merged.Add(a[i]);
    i += 1;
  end;

  while j < b.Length do
  begin
    merged.Add(b[j]);
    j += 1;
  end;

  Result := merged.ToArray;
end;

function LongestRepeatUnitLen(s: string): integer;
begin
  // Find the longest prefix whose repetition forms the whole string.
  var n := s.Length;
  if n = 0 then
  begin
    Result := 0; exit;
  end;
  // Check divisors of n in descending order to find longest repeating unit
  var bestLen := 1;
  var d := n;
  while d >= 1 do
  begin
    if (n mod d = 0) then
    begin
      var rep := s.Substring(0, d);
      var ok := True;
      var k := 1;
      while (k * d) < n do
      begin
        if s.Substring(k * d, d) <> rep then
        begin
          ok := False; break;
        end;
        k += 1;
      end;
      if ok then
      begin
        bestLen := d;
        // since we iterate descending, the first valid d is the longest
        Result := bestLen; exit;
      end;
    end;
    d -= 1;
  end;
  Result := bestLen;
end;

function MinRemoveIntervals(intervals: array of array of integer): integer;
begin
  if (intervals = nil) or (intervals.Length = 0) then
  begin
    Result := 0; exit;
  end;
  // Sort intervals by end ascending
  var idxs := new List<integer>;
  for var i := 0 to intervals.Length - 1 do idxs.Add(i);
  idxs.Sort((a,b)->
  begin
    var ea := intervals[a][1];
    var eb := intervals[b][1];
    if ea < eb then Result := -1 else if ea > eb then Result := 1 else Result := 0;
  end);

  var kept := 0;
  var lastEnd := -MaxInt; // very small
  foreach var i in idxs do
  begin
    var st := intervals[i][0];
    var en := intervals[i][1];
    if st >= lastEnd then
    begin
      kept += 1;
      lastEnd := en;
    end;
  end;
  Result := intervals.Length - kept;
end;

function MinOpsReduceToZero(nums: array of integer; x: integer): integer;
begin
  // Equivalent: find longest subarray whose sum is total - x
  var n := nums.Length;
  var total := 0;
  for var i := 0 to n - 1 do total += nums[i];
  var target := total - x;
  if target < 0 then begin Result := -1; exit; end;
  if target = 0 then begin Result := n; exit; end;

  var left := 0;
  var cur := 0;
  var bestLen := -1;
  for var right := 0 to n - 1 do
  begin
    cur += nums[right];
    while (left <= right) and (cur > target) do
    begin
      cur -= nums[left];
      left += 1;
    end;
    if cur = target then
      bestLen := Max(bestLen, right - left + 1);
  end;
  if bestLen = -1 then Result := -1
  else Result := n - bestLen;
end;

function MaxSubarraySum(arr: array of integer): integer;
begin
  if (arr = nil) or (arr.Length = 0) then begin Result := 0; exit; end;
  var best := arr[0];
  var cur := arr[0];
  for var i := 1 to arr.Length - 1 do
  begin
    cur := Max(arr[i], cur + arr[i]);
    best := Max(best, cur);
  end;
  Result := best;
end;

function NextPowerOfTwo(n: integer): integer;
begin
  if n <= 1 then begin Result := 1; exit; end;
  var v := 1;
  while v < n do v := v shl 1;
  Result := v;
end;

function IsAlnumPalindrome(s: string): boolean;
begin
  var i := 0; var j := s.Length - 1;
  while i < j do
  begin
    while (i < j) and (not Char.IsLetterOrDigit(s[i])) do i += 1;
    while (i < j) and (not Char.IsLetterOrDigit(s[j])) do j -= 1;
    if i < j then
    begin
      if Char.ToLower(s[i]) <> Char.ToLower(s[j]) then
      begin
        Result := False; exit;
      end;
      i += 1; j -= 1;
    end;
  end;
  Result := True;
end;

function HasAdjacentZeros(a: array of integer): boolean;
begin
  for var i := 0 to a.Length - 2 do
    if (a[i] = 0) and (a[i+1] = 0) then
    begin Result := True; exit; end;
  Result := False;
end;

function SumBinaryDigits(x: integer): integer;
begin
  var cnt := 0;
  var v := Abs(x);
  while v > 0 do
  begin
    if (v and 1) = 1 then cnt += 1;
    v := v shr 1;
  end;
  Result := cnt;
end;

function MinWindowSubstring(s, t: string): string;
begin
  if (t = '') or (s = '') then begin Result := ''; exit; end;
  var need := new Dictionary<char,integer>;
  foreach var ch in t do
    if need.ContainsKey(ch) then need[ch] += 1 else need[ch] := 1;
  var have := 0;
  var required := need.Count;
  var left := 0;
  var minLen := MaxInt;
  var minL := 0;
  var windowCounts := new Dictionary<char,integer>;

  for var right := 0 to s.Length - 1 do
  begin
    var rc := s[right];
    if windowCounts.ContainsKey(rc) then windowCounts[rc] += 1 else windowCounts[rc] := 1;
    if need.ContainsKey(rc) and (windowCounts[rc] = need[rc]) then
      have += 1;

    while (have = required) and (left <= right) do
    begin
      var curLen := right - left + 1;
      if curLen < minLen then
      begin
        minLen := curLen; minL := left;
      end;
      var lc := s[left];
      windowCounts[lc] -= 1;
      if need.ContainsKey(lc) and (windowCounts[lc] < need[lc]) then
        have -= 1;
      left += 1;
    end;
  end;

  if minLen = MaxInt then Result := '' else Result := s.Substring(minL, minLen);
end;

function LargestBinaryImageOverlap(A, B: array of array of integer): integer;
begin
  var n := A.Length;
  if (n = 0) then begin Result := 0; exit; end;
  var m := A[0].Length;
  var best := 0;
  // Try all translations: shiftB relative to A
  for var dx := -(n-1) to (n-1) do
    for var dy := -(m-1) to (m-1) do
    begin
      var cur := 0;
      for var i := 0 to n - 1 do
        for var j := 0 to m - 1 do
        begin
          var ii := i + dx;
          var jj := j + dy;
          if (ii >= 0) and (ii < n) and (jj >= 0) and (jj < m) then
            if (A[i][j] = 1) and (B[ii][jj] = 1) then cur += 1;
        end;
      if cur > best then best := cur;
    end;
  Result := best;
end;

function RectanglesOverlap(r1, r2: array of integer): boolean;
begin
  // Each rectangle given as [x1,y1,x2,y2] where (x1,y1) is bottom-left and (x2,y2) is top-right
  if (r1[2] <= r2[0]) or (r2[2] <= r1[0]) then begin Result := False; exit; end; // one is left of other
  if (r1[3] <= r2[1]) or (r2[3] <= r1[1]) then begin Result := False; exit; end; // one is below other
  Result := True;
end;

function ReplaceAll(s, pattern, replacement: string): string;
begin
  if (pattern = '') then begin Result := s; exit; end;
  // Use .Replace which replaces all non-overlapping occurrences
  Result := s.Replace(pattern, replacement);
end;

function CanPartition(nums: array of integer): boolean;
begin
  var total := 0;
  foreach var v in nums do total += v;
  if (total mod 2) <> 0 then begin Result := False; exit; end;
  var target := total div 2;
  var reachable := new boolean[target + 1];
  reachable[0] := True;
  foreach var v in nums do
  begin
    for var s := target downto v do
      if reachable[s - v] then reachable[s] := True;
  end;
  Result := reachable[target];
end;

function ScaleToMatrix(lists: array of array of integer; scalar: integer): array [,] of integer;
begin
  var rows := lists.Length;
  if rows = 0 then
    exit(new integer[0, 0]);
  var cols := lists[0].Length;
  Result := new integer[rows, cols];
  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
      Result[i, j] := lists[i][j] * scalar;
end;

function ElementwiseProduct(a, b: array of integer): array of integer;
begin
  var n := Min(a.Length, b.Length);
  var out := new integer[n - 1];
  for var i := 0 to n - 1 do
    out[i] := a[i] * b[i];
  Result := out;
end;

function RepeatedNTimes(nums: array of integer): integer;
begin
  var counts := new Dictionary<integer,integer>;
  foreach var v in nums do
  begin
    if counts.ContainsKey(v) then counts[v] += 1 else counts[v] := 1;
    if counts[v] > 1 then // the repeated element will quickly exceed 1 often
    begin
      if counts[v] >= nums.Length div 2 then begin Result := v; exit; end;
    end;
  end;
  // fallback: find max count
  var best := nums[0]; var bestCnt := 0;
  foreach var kv in counts do
    if kv.Value > bestCnt then begin bestCnt := kv.Value; best := kv.Key; end;
  Result := best;
end;

function SmallestVertices(n: integer; edges: array of array of integer): array of integer;
begin
  var indeg := new integer[n - 1];
  for var i := 0 to n - 1 do indeg[i] := 0;
  for var e := 0 to edges.Length - 1 do
  begin
    var toNode := edges[e][1];
    indeg[toNode] += 1;
  end;
  var res := new List<integer>;
  for var i := 0 to n - 1 do
    if indeg[i] = 0 then res.Add(i);
  Result := res.ToArray;
end;

function MinPerimeterForArea(areaVal: integer): integer;
begin
  if areaVal <= 0 then begin Result := 0; exit; end;
  var best := MaxInt;
  var i := 1;
  while i * i <= areaVal do
  begin
    if (areaVal mod i) = 0 then
    begin
      var j := areaVal div i;
      var p := 2 * (i + j);
      if p < best then best := p;
    end;
    i += 1;
  end;
  Result := best;
end;

function ModPow(baseVal: Int64; exponentVal: Int64; modulusVal: Int64): Int64;
begin
  if modulusVal = 1 then begin Result := 0; exit; end;
  var res := Int64(1) mod modulusVal;
  var a := (baseVal mod modulusVal + modulusVal) mod modulusVal;
  var e := exponentVal;
  while e > 0 do
  begin
    if (e and 1) = 1 then res := (res * a) mod modulusVal;
    a := (a * a) mod modulusVal;
    e := e shr 1;
  end;
  Result := res;
end;

function NegativesToSquares(nums: array of integer): Dictionary<integer, integer>;
begin
  var map := new Dictionary<integer, integer>;
  foreach var v in nums do
    if v < 0 then
      if not map.ContainsKey(v) then map[v] := v * v;
  Result := map;
end;

function MaxSubarraySumK(arr: array of integer; k: integer): integer;
begin
  if (arr = nil) or (k <= 0) or (k > arr.Length) then
  begin
    Result := 0;
    exit;
  end;

  var windowSum := 0;
  for var i := 0 to k - 1 do
    windowSum += arr[i];
  var best := windowSum;

  for var i := k to arr.Length - 1 do
  begin
    windowSum := windowSum + arr[i] - arr[i - k];
    if windowSum > best then best := windowSum;
  end;

  Result := best;
end;

function ReverseWordsInStrings(stringsArr: array of string): array of string;
begin
  if stringsArr = nil then
  begin
    Result := new string[0];
    exit;
  end;
  var n := stringsArr.Length;
  SetLength(Result, n);
  for var i := 0 to n - 1 do
  begin
    var words := stringsArr[i].Split(' ');
    var outWords := new List<string>;
    for var w := 0 to words.Length - 1 do
      outWords.Add(new string(words[w].ToCharArray.Reverse.ToArray));
    Result[i] := String.Join(' ', outWords);
  end;
end;

function MaxDictDepth(obj: object): integer;
begin
  // Computes maximum nesting depth of dictionaries. Non-dictionary values count as depth 0.
  if obj = nil then begin Result := 0; exit; end;
  var dictType := typeof(System.Collections.Generic.Dictionary<string, object>);
  if obj.GetType() <> dictType then
  begin
    // If it's not the expected dictionary type, check assignability
    if not (obj is System.Collections.Generic.IDictionary<string, object>) then
    begin
      Result := 0; exit;
    end;
  end;

  var queue := new List<object>;
  queue.Add(obj);
  var depth := 0;
  while queue.Count > 0 do
  begin
    var nextLevel := new List<object>;
    foreach var item in queue do
    begin
      var d := item as System.Collections.Generic.IDictionary<string, object>;
      if d <> nil then
      begin
        foreach var kv in d do
          if (kv.Value <> nil) and (kv.Value is System.Collections.Generic.IDictionary<string, object>) then
            nextLevel.Add(kv.Value);
      end;
    end;
    depth += 1;
    queue := nextLevel;
  end;
  Result := depth;
end;

function RearrangeNoAdjacent(s: string): string;
begin
  if s = '' then begin Result := ''; exit; end;
  var counts := new Dictionary<char,integer>;
  foreach var ch in s do
    if counts.ContainsKey(ch) then counts[ch] += 1 else counts[ch] := 1;

  var maxCount := 0; var maxChar := #0;
  foreach var kv in counts do
    if kv.Value > maxCount then begin maxCount := kv.Value; maxChar := kv.Key; end;

  if maxCount > (s.Length + 1) div 2 then begin Result := ''; exit; end;

  // Greedy rebuild using a list of pairs sorted by remaining count
  var resultChars := new List<char>;
  var pq := new List<(char,integer)>;
  foreach var kv in counts do pq.Add((kv.Key, kv.Value));

  while pq.Count > 0 do
  begin
    pq.Sort((a,b)-> if a.Item2 > b.Item2 then Result := -1 else if a.Item2 < b.Item2 then Result := 1 else Result := 0);
    var first := pq[0];
    // pick first
    resultChars.Add(first.Item1);
    first := (first.Item1, first.Item2 - 1);
    pq.RemoveAt(0);
    if pq.Count = 0 then
    begin
      if first.Item2 > 0 then begin Result := ''; exit; end;
      break;
    end;
    // pick second
    pq.Sort((a,b)-> if a.Item2 > b.Item2 then Result := -1 else if a.Item2 < b.Item2 then Result := 1 else Result := 0);
    var second := pq[0];
    resultChars.Add(second.Item1);
    second := (second.Item1, second.Item2 - 1);
    pq.RemoveAt(0);
    if first.Item2 > 0 then pq.Add(first);
    if second.Item2 > 0 then pq.Add(second);
  end;

  Result := new string(resultChars.ToArray);
end;

function IsBalancedParentheses(s: string): boolean;
