  var digit := 1;
  while True do
  begin
    var rangeOfDigits := 9 * (Round(Power(10, digit - 1))) * digit;
    if n <= rangeOfDigits + count then
      break;
    count += rangeOfDigits;
    digit += 1;
  end;
  n -= count;
  var number := Round(Power(10, digit - 1)) + (n - 1) div digit;
  var numStr := number.ToString;
  if digit > 1 then
    Result := StrToInt(numStr[(n - 1) mod digit + 1])
  else
    Result := number;
end;

function RadixSort(nums: array of integer): array of integer;

  function MaxBits(nums: array of integer): integer;
  begin
    var maxNum := nums.Max;
    var bits := 0;
    while maxNum > 0 do
    begin
      maxNum := maxNum div 10;
      bits += 1;
    end;
    Result := bits;
  end;

  function GetDigit(num: integer; ind: integer): integer;
  begin
    Result := (num div (Round(Power(10, ind)))) mod 10;
  end;

begin
  var digits := MaxBits(nums);
  for var d := 0 to digits - 1 do
  begin
    var buckets := new List<integer>[10];
    for var i := 0 to 9 do
      buckets[i] := new List<integer>;
    foreach var num in nums do
    begin
      var digit := GetDigit(num, d);
      buckets[digit].Add(num);
    end;
    var tempList := new List<integer>;
    for var i := 0 to 9 do
      tempList.AddRange(buckets[i]);
    nums := tempList.ToArray;
  end;
  Result := nums;
end;

