    var second := tuple[1];
    if (first < 0) or (first >= R) or (second < 0) or (second >= C) then
    begin
      Result := False;
      exit;
    end;
    for var k := 0 to C - 1 do
      if (matrix[first, k] = 0) and not zeros.Contains((first, k)) then
      begin
