        n -= 1
      else
        n += 1;
    end;
    steps += 1;
  end;
  Result := steps;
end;

function IsArmstrong(num: integer): boolean;
begin
  var strNum := num.ToString;
  var order := strNum.Length;
  var sum := 0;
  var temp := num;
  while temp > 0 do
  begin
    var digit := temp mod 10;
    sum += Round(Power(digit, order));
    temp := temp div 10;
  end;
  Result := num = sum;
end;

function SumOfPowersOf2(lst: array of integer): integer;
begin
  var powerOf2 := new List<integer>;
  foreach var num in lst do
    if (num <> 0) and ((num and (num - 1)) = 0) then
      powerOf2.Add(num);
  Result := powerOf2.Sum;
end;

function SumDivisibleBy3Or5(n: integer): integer;
begin
  var sum := 0;
  for var i := 0 to n do
    if (i mod 3 = 0) or (i mod 5 = 0) then
      sum += i;
  Result := sum;
end;

function MaxCharacters(words: array of string): integer;
begin
  var maxChars := 0;
  foreach var word in words do
    maxChars += word.Length;
  Result := maxChars;
end;

function MinimumOperationsToPalindrome(s: string): integer;
begin
  var n := s.Length;
  var dp := new integer[n, n];
  for var len := 2 to n do
  begin
    for var i := 0 to n - len do
    begin
      var j := i + len - 1;
      if s[i + 1] = s[j + 1] then
        dp[i, j] := dp[i + 1, j - 1]
      else
        dp[i, j] := Min(dp[i + 1, j], dp[i, j - 1]) + 1;
    end;
  end;
  Result := dp[0, n - 1];
end;

function UnionSortedLists(list1, list2: array of integer): array of integer;
begin
  var i := 0;
  var j := 0;
  var unionList := new List<integer>;
  while (i < list1.Length) and (j < list2.Length) do
  begin
    if list1[i] < list2[j] then
    begin
      unionList.Add(list1[i]);
      i += 1;
    end
    else if list1[i] > list2[j] then
    begin
      unionList.Add(list2[j]);
      j += 1;
    end
    else
    begin
      unionList.Add(list1[i]);
      i += 1;
      j += 1;
    end;
  end;
  while i < list1.Length do
  begin
    unionList.Add(list1[i]);
    i += 1;
  end;
  while j < list2.Length do
  begin
    unionList.Add(list2[j]);
    j += 1;
  end;
  Result := unionList.ToArray;
end;

