function Rotate2DList(matrix: array[,] of integer): array[,] of integer;
begin
  var rows := matrix.GetLength(0);
  var cols := matrix.GetLength(1);
  var res := new integer[cols, rows];
  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
      res[j, rows - 1 - i] := matrix[i, j];
  Result := res;
end;

