  foreach var word in parts do
    if (word <> '') and (LowerCase(word[1]) = LowerCase(startChar)) then
      resultList.Add(word);
  Result := resultList.ToArray;
end;

function MostOccurringChar(inputString: string): char;
begin
  var frequency := new Dictionary<char, integer>;
  var maxFreq := 0;
  var maxChar := #0;
  foreach var char in inputString do
  begin
    if frequency.ContainsKey(char) then
      frequency[char
    ] += 1
    else
      frequency[char
    ] := 1;
    if frequency[char
    ] > maxFreq then
    begin
      maxFreq := frequency[char
    ];
      maxChar := char;
    end;
  end;
  Result := maxChar;
end;

