function GetPrevNumber(n: integer): integer;
begin
  var s := n.ToString;
  var l := s.Length;
  for var i := l - 1 downto 1 do
  begin
    if s[i
    ] < s[i - 1
    ] then
    begin
      var m := s[i - 1
    ];
      var chars := s.ToCharArray;
      chars[i - 1
    ] := chars[i
    ];
      chars[i
    ] := m;
      s := new string(chars);
      s := s[
      :i
    ] + new string(s[i:
    ].Order.ToArray);
      if s[
      1
    ] = '0' then
        Result := -1
      else
        Result := StrToInt(s);
