end;

function UniqueRobotPaths(m, n: integer): integer;
begin
  var dp := new integer[m, n];
  dp[0, 0] := 1;
  for var r := 0 to m - 1 do
    for var c := 0 to n - 1 do
    begin
      if r > 0 then
        dp[r, c] += dp[r - 1, c];
      if c > 0 then
        dp[r, c] += dp[r, c - 1];
    end;
  Result := dp[m - 1, n - 1];
end;

function FactorialDigitCount(n: integer): integer;
begin
  if n = 0 then
  begin
    Result := 1;
    exit;
  end;
  var digits := n * Log10(n / Exp(1)) + Log10(2 * Pi * n) / 2;
  Result := integer(digits) + 1;
end;

function CountPositives(matrix: array [,] of integer): integer;
