end;

function FindMinAbsDifference(nums: array of integer): integer;
begin
  nums := nums.Order.ToArray;
  var minDiff := integer.MaxValue;
  for var i := 1 to nums.Length - 1 do
  begin
    var diff := Abs(nums[i
    ] - nums[i - 1
    ]);
    if diff < minDiff then
      minDiff := diff;
  end;
  Result := minDiff;
end;

