function IsCorrectCapitalization(word: string): boolean;
begin
  if (word = word.ToUpper) then
  begin
    Result := True;
    exit;
  end;
  if (word = word.ToLower) then
  begin
    Result := True;
    exit;
  end;

  if (word.Length > 0) and (word[1] = word[1].ToUpper) and
     (word.Substring(1) = word.Substring(1).ToLower) then
  begin
    Result := True;
    exit;
  end;

  Result := False;
end;

