    else if bill = 10 then
    begin
      if five = 0 then
      begin
        Result := False;
        exit;
      end;
      five -= 1;
      ten += 1;
    end
    else
    begin
      if (ten > 0) and (five > 0) then
      begin
        ten -= 1;
        five -= 1;
      end
      else if five >= 3 then
        five -= 3
      else
      begin
