function LenLongestSubstring(s: string): integer;
begin
  var last := new Dictionary<char, integer>;
  var left := 0;
  var best := 0;

  for var right := 0 to s.Length - 1 do
  begin
    var c := s[right + 1];

    if last.ContainsKey(c) and (last[c] >= left) then
      left := last[c] + 1;

    last[c] := right;

    var cur := right - left + 1;
    if cur > best then best := cur;
  end;

  Result := best;
end;

