function MaxInSubarrays(arr: array of integer; k: integer): array of integer;
begin
  if (arr.Length = 0) or (k <= 0) then
  begin
    Result := nil;
    exit;
  end;
  var resultList := new List<integer>;
  var deque := new Queue<integer>;
  for var i := 0 to arr.Length - 1 do
  begin
    while (deque.Count > 0) and (deque.Peek <= i - k) do
      deque.Dequeue;
    while (deque.Count > 0) and (arr[deque.Peek] <= arr[i]) do
      deque.Dequeue;
    deque.Enqueue(i);
    if i >= k - 1 then
      resultList.Add(arr[deque.Peek]);
  end;
  Result := resultList.ToArray;
end;

function MinCostPath(matrix: array [,] of integer): integer;
