function LongestConsecutiveChar(s: string): (char, integer);
begin
  if s.Length = 0 then
  begin
    Result := (#0, 0);
    exit;
  end;

  var maxCount := 1;
  var maxChar := s[1];
  var count := 1;

  for var i := 2 to s.Length do
  begin
    if s[i] = s[i - 1] then
      count += 1
    else
    begin
      if count > maxCount then
      begin
        maxCount := count;
        maxChar := s[i - 1];
      end;
      count := 1;
    end;
  end;

  if count > maxCount then
  begin
    maxCount := count;
    maxChar := s[s.Length];
  end;

  Result := (maxChar, maxCount);
end;

