    Result := 0;
    exit;
  end;

  var profit := 0;
  var minPrice := prices[0];

  foreach var price in prices do
  begin
    profit := Max(profit, price - minPrice);
    minPrice := Min(minPrice, price);
  end;

  Result := profit;
end;

