procedure Backtrack(i: integer; current: string; const S: string; var result: List<string>);
begin
  if i >= S.Length then
  begin
    result.Add(current);
    exit;
  end;

  Backtrack(i + 1, current + S[i + 1], S, result);

  if S[i + 1].IsLetter then
  begin
    if S[i + 1].IsLower then
      Backtrack(i + 1, current + S[i + 1].ToUpper, S, result)
    else
      Backtrack(i + 1, current + S[i + 1].ToLower, S, result);
  end;
end;

function CasePermutation(S: string): List<string>;
begin
  var res := new List<string>;
  Backtrack(0, '', S, res);
  Result := res;
end;

function MaxSumTwoSubarrays(A: array of integer; L, M: integer): integer;
begin
  var preSum := ArrFill(A.Length + 1, 0);
  for var i := 1 to preSum.Length - 1 do
    preSum[i] := preSum[i - 1] + A[i - 1];

  var Lmax := preSum[L];
  var Mmax := preSum[M];
  var ans := preSum[L + M];

  for var i := L + M + 1 to preSum.Length - 1 do
  begin
    Lmax := Max(Lmax, preSum[i - M] - preSum[i - M - L]);
    Mmax := Max(Mmax, preSum[i - L] - preSum[i - L - M]);
    ans := Max(ans, Lmax + preSum[i] - preSum[i - M], Mmax + preSum[i] - preSum[i - L]);
  end;

  Result := ans;
end;

function FindSubarraysWithGivenSum(nums: array of integer; k: integer): integer;
begin
