  var dictSum := new Dictionary<integer, integer>;
  dictSum[0] := 1;

  for var i := 0 to nums.Length - 1 do
  begin
    currentSum += nums[i];
    if dictSum.ContainsKey(currentSum - k) then
      count += dictSum[currentSum - k];

    if dictSum.ContainsKey(currentSum) then
      dictSum[currentSum] += 1
    else
      dictSum[currentSum] := 1;
  end;

  Result := count;
end;

