end;

procedure Permute(perm: List<integer>; remainingNums: List<integer>; var results: List<List<integer>>);
begin
  if remainingNums.Count = 0 then
  begin
    results.Add(new List<integer>(perm));
    exit;
  end;

  for var i := 0 to remainingNums.Count - 1 do
  begin
    if (i > 0) and (remainingNums[i] = remainingNums[i - 1]) then
      continue;

    var newPerm := new List<integer>(perm);
    newPerm.Add(remainingNums[i]);

    var newRemainingNums := new List<integer>(remainingNums);
    newRemainingNums.RemoveAt(i);

    Permute(newPerm, newRemainingNums, results);
  end;
end;

function GeneratePerms(nums: array of integer): List<List<integer>>;
begin
  var results := new List<List<integer>>;
  var sortedNums := nums.ToList;
  sortedNums.Sort;
  Permute(new List<integer>, sortedNums, results);
  Result := results;
end;

function DifferenceSortedArrays(arr1, arr2: array of integer): List<integer>;
begin
  var difference := new List<integer>;
  var p1 := 0;
  var p2 := 0;

  while (p1 < arr1.Length) and (p2 < arr2.Length) do
  begin
    if arr1[p1] < arr2[p2] then
    begin
      difference.Add(arr1[p1]);
      p1 += 1;
    end
    else if arr1[p1] > arr2[p2] then
      p2 += 1
    else
    begin
      p1 += 1;
      p2 += 1;
    end;
  end;

  while p1 < arr1.Length do
  begin
    difference.Add(arr1[p1]);
    p1 += 1;
  end;

  Result := difference;
end;

