function Height(node: BinaryTree): integer;
begin
  if node = nil then
  begin
    Result := 0;
    exit;
  end;
  Result := 1 + Max(Height(node.Left), Height(node.Right));
end;

function IsBalancedTree(root: BinaryTree): boolean;
begin
  if root = nil then
  begin
    Result := True;
    exit;
  end;

  var leftHeight := Height(root.Left);
  var rightHeight := Height(root.Right);

  if (Abs(leftHeight - rightHeight) <= 1) and IsBalancedTree(root.Left) and IsBalancedTree(root.Right) then
    Result := True
  else
    Result := False;
end;

function FindSubarraySum(arr: array of integer; k: integer): integer;
begin
  var count := 0;
  var sum := 0;
  var hashMap := new Dictionary<integer, integer>;
  hashMap[0] := 1;

  for var i := 0 to arr.Length - 1 do
  begin
    sum += arr[i];
    if hashMap.ContainsKey(sum - k) then
      count += hashMap[sum - k];

    if hashMap.ContainsKey(sum) then
      hashMap[sum] += 1
    else
      hashMap[sum] := 1;
  end;

  Result := count;
end;

function ReverseAndCapitalize(sentence: string): string;
begin
  var words := sentence.ToWords;
  var reversedWords := new List<string>;

  for var i := words.Length - 1 downto 0 do
  begin
    var word := words[i];
    if word.Length > 0 then
      reversedWords.Add(word[1].ToUpper + word.Substring(2).ToLower)
    else
      reversedWords.Add(word);
  end;

  Result := string.Join(' ', reversedWords);
end;

function Merge(var arr, tempArr: array of integer; left, mid, right: integer): integer;
begin
  var i := left;
  var j := mid + 1;
  var k := left;
  var invCount := 0;

  while (i <= mid) and (j <= right) do
  begin
    if arr[i] <= arr[j] then
    begin
      tempArr[k] := arr[i];
      k += 1;
      i += 1;
    end
    else
    begin
      tempArr[k] := arr[j];
      invCount += (mid - i + 1);
      k += 1;
      j += 1;
    end;
  end;

  while i <= mid do
  begin
    tempArr[k] := arr[i];
    k += 1;
    i += 1;
  end;

  while j <= right do
  begin
    tempArr[k] := arr[j];
    k += 1;
    j += 1;
  end;

  for var idx := left to right do
    arr[idx] := tempArr[idx];

  Result := invCount;
end;

function MergeSort(var arr, tempArr: array of integer; left, right: integer): integer;
begin
  var invCount := 0;
  if left < right then
  begin
    var mid := (left + right) div 2;

    invCount += MergeSort(arr, tempArr, left, mid);
    invCount += MergeSort(arr, tempArr, mid + 1, right);
    invCount += Merge(arr, tempArr, left, mid, right);
  end;
  Result := invCount;
end;

function CountInversions(arr: array of integer): integer;
begin
  var tempArr := new integer[arr.Length];
