function LongestPalindromeSubseq(s: string): integer;
begin
  var n := s.Length;
  var dp := new integer[n, n];

  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 1;
    for var j := i + 1 to n - 1 do
    begin
      if s[i + 1] = s[j + 1] then
        dp[i, j] := dp[i + 1, j - 1] + 2
      else
        dp[i, j] := Max(dp[i + 1, j], dp[i, j - 1]);
    end;
  end;

  Result := dp[0, n - 1];
end;

