  foreach var letter in s do
    if char.IsLetterOrDigit(letter) then
    begin
      var lowerLetter := letter.ToLower;
      if letterCount.ContainsKey(lowerLetter) then
        letterCount[lowerLetter] += 1
      else
        letterCount.Add(lowerLetter, 1);
    end;

  var oddCount := 0;
  foreach var count in letterCount.Values do
    if count mod 2 <> 0 then
      oddCount += 1;

  Result := oddCount <= 1;
end;

function SumOfLargestSubarray(nums: array of integer): integer;
begin
  var maxCurrent := nums[0];
  var maxGlobal := nums[0];

  for var i := 1 to nums.Length - 1 do
  begin
    maxCurrent := Max(nums[i], maxCurrent + nums[i]);
    if maxCurrent > maxGlobal then
      maxGlobal := maxCurrent;
  end;

  Result := maxGlobal;
end;

function BuyAndSellTwoAtMost(prices: array of integer): integer;
begin
  if (prices.Length = 0) or (prices.Length < 2) then
  begin
    Result := 0;
    exit;
  end;

  var dp := new integer[prices.Length, 4];
  dp[0,0] := 0;
  dp[0,1] := -prices[0];
  dp[0,2] := 0;
  dp[0,3] := -prices[0];

  for var i := 1 to prices.Length - 1 do
  begin
    dp[i,0] := dp[i-1,0];
    dp[i,1] := Max(dp[i-1,1], dp[i-1,0] - prices[i]);
    dp[i,2] := Max(dp[i-1,2], dp[i-1,1] + prices[i]);
    dp[i,3] := Max(dp[i-1,3], dp[i-1,2] - prices[i]);
  end;

  Result := Max(dp[prices.Length-1,2], dp[prices.Length-1,3] + prices[prices.Length-1]);
end;

function IsRearrangeable(s: string): boolean;
