      cnt.Add(ch, 1);

  var maxCount := cnt.Values.Max;

  if (s.Length mod 2 = 1) and (maxCount > s.Length div 2 + 1) then
    Result := False
  else if (s.Length mod 2 = 0) and (maxCount > s.Length div 2) then
    Result := False
  else
    Result := True;
end;

