function CountPrimeNumbers(n: integer): integer;

  function IsPrime(num: integer): boolean;
  begin
    if num <= 1 then
      Result := False
    else if num = 2 then
      Result := True
    else if num mod 2 = 0 then
      Result := False
    else
    begin
      var i := 3;
      while i * i <= num do
      begin
        if num mod i = 0 then
        begin
          Result := False;
          exit;
        end;
        i += 2;
      end;
      Result := True;
    end;
  end;

begin
  var count := 0;
  for var num := 2 to n - 1 do
    if IsPrime(num) then
      count += 1;
  Result := count;
end;

function MinSubArrayLength(nums: array of integer; target: integer): integer;
begin
  var n := nums.Length;
  var minLen := n + 1;
  var left := 0;
  var currentSum := 0;

  for var right := 0 to n - 1 do
  begin
    currentSum += nums[right];
    while currentSum >= target do
    begin
      minLen := Min(minLen, right - left + 1);
      currentSum -= nums[left];
      left += 1;
    end;
  end;

  if minLen <= n then
    Result := minLen
  else
    Result := 0;
end;

function MaxSubArrayProduct(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var maxProduct := nums[0];
  var minProduct := nums[0];
  var resultVal := maxProduct;

  for var i := 1 to nums.Length - 1 do
  begin
    var temp := maxProduct;
    maxProduct := Max(nums[i], Max(maxProduct * nums[i], minProduct * nums[i]));
    minProduct := Min(nums[i], Min(temp * nums[i], minProduct * nums[i]));
    resultVal := Max(resultVal, maxProduct);
  end;

  Result := resultVal;
end;

