  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    if dic.ContainsKey(ch) and (startIndex <= dic[ch]) then
      startIndex := dic[ch] + 1
    else
      maxLength := Max(maxLength, i - startIndex + 1);

    dic[ch] := i;
  end;

  Result := maxLength;
end;

