    else
      counts.Add(num, 1);

  var ans := new List<integer>;
  var threshold := nums.Length div 3;

  foreach var pair in counts do
    if pair.Value > threshold then
      ans.Add(pair.Key);

  Result := ans.ToArray;
end;

