function MinSessions(tasks: array of integer; sessionTime: integer): integer;
begin
  var n := tasks.Length;
  var status := 1 shl n;

  var nums := new integer[status];
  var lasts := new integer[status];

  for var i := 0 to status - 1 do
  begin
    nums[i] := n;
    lasts[i] := sessionTime;
  end;

  nums[0] := 1;
  lasts[0] := 0;

  for var i := 1 to status - 1 do
  begin
    for var j := 0 to n - 1 do
    begin
      var todo := i and (1 shl (n - 1 - j));
      if todo <> 0 then
      begin
        var pre := i - (1 shl (n - 1 - j));
        var lastVal := lasts[pre] + tasks[j];
        var numVal := nums[pre];

        if lastVal > sessionTime then
        begin
          numVal += 1;
          lastVal := tasks[j];
        end;

        if (numVal < nums[i]) or ((numVal = nums[i]) and (lastVal < lasts[i])) then
        begin
          nums[i] := numVal;
          lasts[i] := lastVal;
        end;
      end;
    end;
  end;

  Result := nums[status - 1];
end;

