function MinJumps(nums: array of integer): integer;
begin
  if nums.Length <= 1 then
  begin
    Result := 0;
    exit;
  end;

  var jumps := 0;
  var currentEnd := 0;
  var farthest := 0;

  for var i := 0 to nums.Length - 2 do
  begin
    farthest := Max(farthest, i + nums[i]);
    if i = currentEnd then
    begin
      jumps += 1;
      currentEnd := farthest;
    end;
  end;

  Result := jumps;
end;

