function PerfectSquares(n: integer): integer;
begin
  var dp := new integer[n + 1];

  for var i := 1 to n do
  begin
    dp[i] := i;

    for var j := 1 to Trunc(Sqrt(i)) do
    begin
      var square := j * j;
      dp[i] := Min(dp[i], dp[i - square] + 1);
    end;
  end;

  Result := dp[n];
end;

function FindPattern(text, pattern: string): integer;
