function NumWaysConsecutiveSum(n: integer): integer;
begin
  var count := 0;

  for var i := 1 to n do
  begin
    var sumVal := 0;

    for var j := i to n do
    begin
      sumVal += j;
      if sumVal = n then
      begin
        count += 1;
        break;
      end
      else if sumVal > n then
        break;
    end;
  end;

  Result := count;
end;

function MinNumberOperations(target: array of integer): integer;
begin
  var n := target.Length;
  var dp := new integer[n];
  dp[0] := target[0];

  for var i := 1 to n - 1 do
  begin
    if target[i] <= target[i - 1] then
      dp[i] := dp[i - 1]
    else
      dp[i] := dp[i - 1] + (target[i] - target[i - 1]);
  end;

  Result := dp[n - 1];
end;

