function CanJump(nums: array of integer): boolean;
begin
  var &end := 0;
  var n := nums.Length;

  for var i := 0 to n - 1 do
  begin
    if i > &end then
    begin
      Result := false;
      exit;
    end;

    if i = n - 1 then
    begin
      Result := true;
      exit;
