  for var i := 0 to arr.Length - 1 do
  begin
    if count.ContainsKey(arr[i]) then
      count[arr[i]] += 1
    else
      count[arr[i]] := 1;
  end;

  for var i := 1 to n do
  begin
    if count.ContainsKey(i) then
    begin
      if count[i] = 2 then
        duplicate := i;
    end
    else
      missing := i;
  end;

  Result := (duplicate, missing);
end;

