function SortColors(nums: List<integer>): List<integer>;
begin
  var low := 0;
  var mid := 0;
  var high := nums.Count - 1;

  while mid <= high do
  begin
    if nums[mid] = 0 then
    begin
      var temp := nums[low];
      nums[low] := nums[mid];
      nums[mid] := temp;
      low += 1;
      mid += 1;
    end
    else if nums[mid] = 1 then
      mid += 1
    else
    begin
      var temp := nums[mid];
      nums[mid] := nums[high];
      nums[high] := temp;
      high -= 1;
    end;
  end;

  Result := nums;
end;

