  var sumValue := 0;
  var sumMap := new Dictionary<integer, integer>;

  for var i := 0 to arr.Count - 1 do
  begin
    sumValue := sumValue + arr[i];
    if sumValue = 0 then
      count := count + 1;

    if sumMap.ContainsKey(sumValue) then
    begin
      count := count + sumMap[sumValue];
      sumMap[sumValue] := sumMap[sumValue] + 1;
    end
    else
      sumMap.Add(sumValue, 1);
  end;

  Result := count;
end;

function Search(row: List<integer>; edge: integer): integer;
begin
  var n := row.Count;
  if edge = n then
    Result := edge
  else
  begin
    var l := edge;
    var r := n - 1;
    while l <= r do
    begin
      var m := l + (r - l) div 2;
      if row[m] >= 0 then
        l := m + 1
      else
        r := m - 1;
    end;
    Result := l;
  end;
end;

function CountNegativeNumbers(grid: List<List<integer>>): integer;
begin
  var m := grid.Count;
  var n := grid[0].Count;
  var edge := 0;
  var count := 0;

  for var i := m - 1 downto 0 do
  begin
    edge := Search(grid[i], edge);
    count := count + n - edge;
  end;

  Result := count;
end;

