function NewmanPrime(n: integer): integer;
begin
  if (n = 0) or (n = 1) then
    Result := 1
  else
  begin
    var a := new List<integer>;
    a.Add(1);
    a.Add(1);

    for var i := 2 to n do
      a.Add(2 * a[i - 1] + a[i - 2]);

    for var i := n downto 0 do
      if IsPrime(a[i]) then
      begin
        Result := a[i];
        exit;
      end;

    Result := -1;
  end;
end;

function FindLeader(arr: List<integer>): List<integer>;
