function MinFlip(arr: array of integer): integer;
begin
  var n := arr.Length;
  var l := 0;
  var r := n - 1;
  var flip := 0;
  while l < r do
  begin
    if arr[l] <> arr[r] then
      flip += 1;
    l += 1;
    r -= 1;
  end;
