function EncodeCipher(str1: string; shift: integer): string;
begin
  var encodedStr := '';
  foreach var ch in str1 do
  begin
    if ch.IsLetter then
    begin
      var shiftAmount := shift mod 26;
      if ch.IsLower then
      begin
        var newChar := Chr(((Ord(ch) - Ord('a') + shiftAmount) mod 26) + Ord('a'));
        encodedStr += newChar;
      end
      else
      begin
        var newChar := Chr(((Ord(ch) - Ord('A') + shiftAmount) mod 26) + Ord('A'));
        encodedStr += newChar;
      end;
    end
    else
      encodedStr += ch;
  end;
  Result := encodedStr;
end;

