      if img1[i, j] = 1 then
        img1Ones.Add((i, j));
      if img2[i, j] = 1 then
        img2Ones.Add((i, j));
    end;

  foreach var (r1, c1) in img1Ones do
    foreach var (r2, c2) in img2Ones do
    begin
      var rowShift := r1 - r2;
      var colShift := c1 - c2;
      var key := (rowShift, colShift);
      if shiftCount.ContainsKey(key) then
        shiftCount[key] += 1
      else
        shiftCount[key] := 1;
      bestMax := Max(bestMax, shiftCount[key]);
    end;

  Result := bestMax;
end;

