    begin
      var ch := s[i];
      if ch = '(' then
        stack.Push(ch)
      else if ch = ')' then
      begin
        if stack.Count = 0 then
        begin
          Result := false;
          exit;
        end
        else
          stack.Pop;
      end;
    end;
    Result := stack.Count = 0;
  end;
end;

