function IsPerfect(n: integer): boolean;
begin
  if n = 1 then
  begin
    Result := False;
    exit;
  end;

  var sum := 1;
  var i := 2;
  while i <= n / i do
  begin
    if n mod i = 0 then
      sum += i + (n div i);
    i += 1;
  end;

  if i * i = n then
    sum -= i;

  Result := sum = n;
end;

