Here is a PascalABC.NET program that removes adjacent duplicate characters
from a string without using built-in string manipulation functions or regular
expressions. For example, 'aabbA' becomes 'abA':

```pascal
function RemoveAdjacentDuplicates(SourceText: string): string;
begin
  if (SourceText = nil) or (SourceText = '') then
  begin
    RemoveAdjacentDuplicates := '';
    exit;
  end;

  var ResultText := '';
  var PreviousChar := SourceText[1];
  ResultText += PreviousChar;

  for var Index := 2 to SourceText.Length do
  begin
    var CurrentChar := SourceText[Index];
    if CurrentChar <> PreviousChar then
      ResultText += CurrentChar;
    PreviousChar := CurrentChar;
  end;

  RemoveAdjacentDuplicates := ResultText;
end;

begin
  var TextValue := 'aabbA';
  var Cleaned := RemoveAdjacentDuplicates(TextValue);
  Println('Original: ', TextValue);
  Println('Without adjacent duplicates: ', Cleaned);
end.
```

Here is an algorithm in PascalABC.NET for computing the factorial of a number.
It uses a recursive implementation whose call depth is equal to the input
value, so extremely large arguments may cause a stack overflow:

```pascal
function Factorial(N: integer): int64;
begin
  if N < 0 then
    raise new ArgumentException('Factorial is not defined for negative numbers.');

  if (N = 0) or (N = 1) then
  begin
    Factorial := 1;
    exit;
  end;

  // Recursive call: depth is proportional to N
  Factorial := N * Factorial(N - 1);
end;

begin
  var N := 10;
  try
    var Value := Factorial(N);
    Println($'{N}! = {Value}');

    // Warning: do not call Factorial with very large values like 100000,
    // because the deep recursion may cause a stack overflow.
  except
    on E: Exception do
      Println('Error: ' + E.Message);
  end;
end.
```

