function SumFirstN(N: BigInteger): BigInteger;
begin
  if N < 0 then
    raise new ArgumentException('N must be non-negative.');

  // Sum = N * (N + 1) / 2
  SumFirstN := N * (N + 1) div 2;
end;

begin
