Here is a PascalABC.NET program that creates a function DoubleValue which
returns double the value of an integer using only bitwise operations. The
function correctly handles negative numbers:

```pascal
function DoubleValue(Num: integer): integer;
begin
  if Num = 0 then
  begin
    DoubleValue := 0;
    exit;
  end;

  var Sign := 1;
  var Value := Num;

  if Value < 0 then
  begin
    Value := -Value;
    Sign := -1;
  end;

  // Left shift by 1 bit doubles the absolute value
  var Doubled := Value shl 1;
  DoubleValue := Doubled * Sign;
end;

begin
  var Samples := Arr(-5, -1, 0, 1, 7);
  foreach var V in Samples do
  begin
    var D := DoubleValue(V);
    Println($'DoubleValue({V}) = {D}');
  end;
end.
