function FibonacciSearch(arr: array of integer; element: integer): integer;
begin
  var n := arr.Length;
  var fib2 := 0;
  var fib1 := 1;
  var fib := fib2 + fib1;

  while fib < n do
  begin
    fib2 := fib1;
    fib1 := fib;
    fib := fib2 + fib1;
  end;

  var offset := -1;

  while fib > 1 do
  begin
    var i := &Min(offset + fib2, n - 1);

    if arr[i] < element then
    begin
      fib := fib1;
      fib1 := fib2;
      fib2 := fib - fib1;
      offset := i;
    end
    else if arr[i] > element then
    begin
      fib := fib2;
      fib1 := fib1 - fib2;
      fib2 := fib - fib1;
    end
    else
    begin
      while (i > 0) and (arr[i - 1] = element) do
        i -= 1;
      exit(i);
    end;
  end;

  if (fib1 = 1) and (arr[offset + 1] = element) then
    exit(offset + 1);

  Result := -1;
end;

