function CalculateArea(side1, side2, side3: real): real;
begin
  if not IsValidTriangle(side1, side2, side3) then
    raise new System.ArgumentException('Invalid triangle: the given side lengths do not form a triangle.');

  var semiPerimeter := (side1 + side2 + side3) / 2;
