```pascal
procedure RemoveOccurrences<T>(var arr: array of T; itemToRemove: T);
begin
  var writeIndex := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    if not &object.Equals(arr[i], itemToRemove) then
    begin
      arr[writeIndex] := arr[i];
      writeIndex += 1;
    end;
  end;

  &Array.Resize(arr, writeIndex);
end;

begin
  // Example usage
  var arr := Arr&<object>(1, '2', 3, '2', 4, '5', 6);
  var itemToRemove := object('2');

