function Factors(N: integer): List<integer>;
begin
  var lst := new List<integer>;
  var i := 2;
  while i * i <= N do
  begin
    while N.Divs(i) do
    begin
      if i not in lst then
        lst.Add(i);
      N := N div i;
    end;
    i += 1;
  end;
  if N >= 2 then
    lst.Add(N);
  Result := lst;
end;

