function Factorize(x: integer): List<integer>;
begin
  Result := new List<integer>;
  if x = 1 then
  begin  
    Result.Add(1);
    exit
  end;  
  var i := 2;
  repeat
    if x.Divs(i) then
    begin
      Result.Add(i);
      x := x div i; 
    end
    else i += 1;
  until x = 1;
end;

