type Point = auto class x,y:integer end;

function NewPos(pos: Point; dir: char): Point;
begin
  case dir of
    '>': Result := new Point(pos.x+1,pos.y);
    '<': Result := new Point(pos.x-1,pos.y);
    '^': Result := new Point(pos.x,pos.y-1);
    'v': Result := new Point(pos.x,pos.y+1);
  end;  
end;

