  foreach var (y,x) in (1..m-2).Cartesian(1..n-2) do
    case InhCount(x,y) of
      0..1,4..9: b[y,x] := 0;
      3: b[y,x] := 1; 
      2: b[y,x] := a[y,x]; 
    end;
  a := Copy(b);
  Draw;
end;

