function FindPaths(m, n: integer): integer;
begin
  var matrix := new integer[m, n];

  for var i := 0 to n - 1 do
    matrix[0, i] := 1;

  for var i := 0 to m - 1 do
    matrix[i, 0] := 1;

  for var i := 1 to m - 1 do
    for var j := 1 to n - 1 do
      matrix[i, j] := matrix[i-1, j] + matrix[i, j-1];

  Result := matrix[m-1, n-1];
end;

function Factorial(n: integer): integer;
begin
  if n = 0 then
    Result := 1
  else
    Result := n * Factorial(n-1);
end;

function SumOfDigitFactorials(num: integer): integer;
begin
  var sum := 0;
  var numStr := num.ToString;
  foreach var ch in numStr do
    sum += Factorial(StrToInt(ch.ToString));
  Result := sum;
end;

function NthNonprime(n: integer): integer;
begin
  var nonPrimes := new List<integer>;
  nonPrimes.Add(1);
  var primeCounter := 2;

  while nonPrimes.Count < n do
  begin
    primeCounter += 1;
    var isPrime := True;

    for var num := 2 to Trunc(Sqrt(primeCounter)) do
      if primeCounter mod num = 0 then
      begin
        isPrime := False;
        break;
      end;

    if not isPrime then
      nonPrimes.Add(primeCounter);
  end;

  Result := nonPrimes.Last;
end;

