  var len := A.Length;
  if len <> B.Length then
  begin
    Result := -1;
    exit;
  end;

  for var i := 1 to len do
  begin
    var rotated := A.Substring(i) + A.Substring(0, i);
    if rotated = B then
    begin
      Result := i;
      exit;
    end;
  end;

  Result := -1;
end;

