    var group := new integer[size];

    for var j := 0 to size - 1 do
      group[j] := lst[i + j];

    groups.Add(group);
  end;

  Result := groups.ToArray;
end;

function SubstringRepeats(source, target: string): integer;
begin
  var sourceChars := source.ToHashSet;

  foreach var ch in target do
    if not sourceChars.Contains(ch) then
    begin
      Result := -1;
      exit;
    end;

  var cnt := 0;
  var idx := 1;
  var repeated := '';

  while idx <= target.Length do
  begin
    cnt += 1;
    repeated := repeated + source;

    if repeated.Contains(target) then
    begin
      Result := cnt;
      exit;
    end;

    if cnt > 100 then // Prevent infinite loop
    begin
      Result := -1;
      exit;
    end;
  end;

  Result := -1;
end;

