function MergeSortedLists(list1, list2: ListNode): ListNode;
begin
  var dummy := new ListNode(0, nil);
  var current := dummy;
  var l1 := list1;
  var l2 := list2;

  while (l1 <> nil) and (l2 <> nil) do
  begin
    if l1.val < l2.val then
    begin
      current.next := l1;
      l1 := l1.next;
    end
    else
    begin
      current.next := l2;
      l2 := l2.next;
    end;
    current := current.next;
  end;

  if l1 <> nil then
    current.next := l1
  else
    current.next := l2;

  Result := dummy.next;
end;

// Helper function to create a linked list from an array of values
function CreateLinkedList(values: array of integer): ListNode;
begin
  if values.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var head := new ListNode(values[0], nil);
  var current := head;

  for var i := 1 to values.Length - 1 do
  begin
    current.next := new ListNode(values[i], nil);
    current := current.next;
  end;

  Result := head;
end;

// Helper function to convert a linked list to an array of values
function ConvertLinkedListToList(linkedList: ListNode): array of integer;
begin
  var values := new List<integer>;
  var current := linkedList;

  while current <> nil do
  begin
    values.Add(current.val);
    current := current.next;
  end;

  Result := values.ToArray;
end;

