  var cols := matrix.GetLength(1);
  var maxValues := new integer[cols];

  for var j := 0 to cols - 1 do
  begin
    var maxVal := matrix[0, j];
    for var i := 1 to rows - 1 do
      if matrix[i, j] > maxVal then
        maxVal := matrix[i, j];
    maxValues[j] := maxVal;
  end;

  Result := maxValues;
end;

function MinimumCoins(coins: array of integer; amount: integer): integer;
begin
  var dp := new integer[amount + 1];

  for var i := 1 to amount do
    dp[i] := integer.MaxValue;

  dp[0] := 0;

  for var i := 1 to amount do
    foreach var coin in coins do
      if i >= coin then
        if dp[i - coin] <> integer.MaxValue then
          dp[i] := Min(dp[i], dp[i - coin] + 1);

  if dp[amount] = integer.MaxValue then
    Result := -1
  else
    Result := dp[amount];
end;

