  var n := grid.GetLength(1);
  var dp := new integer[m, n];

  dp[0, 0] := 1;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if i > 0 then
        dp[i, j] += dp[i-1, j];
      if j > 0 then
        dp[i, j] += dp[i, j-1];
    end;

  Result := dp[m-1, n-1];
end;

