function ConvertToBits(A, B: integer): integer;
begin
  var xorResult := A xor B;
  var bitCount := 0;
  var temp := xorResult;

  while temp <> 0 do
  begin
    bitCount += temp and 1;
    temp := temp shr 1;
  end;

  Result := bitCount;
end;

