function PrimeFibonacci(n: integer): int64;
begin
  var found := 0;
  var a: int64 := 0;
  var b: int64 := 1;

  while found < n do
  begin
    var c := a + b;
    a := b;
    b := c;

    if IsPrime(b) then
      found += 1;
  end;

  Result := b;
end;

