function FindMaxDiff(arr: array of integer): integer;
begin
  var maxDiff := 0;
  var minElement := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    if arr[i] - minElement > maxDiff then
      maxDiff := arr[i] - minElement;

    if arr[i] < minElement then
      minElement := arr[i];
  end;

  Result := maxDiff;
end;

function GCD(a, b: integer): integer;
begin
  while b <> 0 do
  begin
    var temp := b;
    b := a mod b;
    a := temp;
  end;
  Result := a;
end;

