  for var i := 0 to grid.GetLength(0) - 1 do
    for var j := 0 to grid.GetLength(1) - 1 do
      if grid[i, j] = 1 then
      begin
        Dfs(grid, i, j);
        count += 1;
      end;

  Result := count;
end;

function FindTwoSum(numbers: array of integer; target: integer): array of integer;
begin
  var numDict := new Dictionary<integer, integer>;

  for var i := 0 to numbers.Length - 1 do
  begin
    var complement := target - numbers[i];

    if numDict.ContainsKey(complement) then
    begin
      Result := [numDict[complement], i];
      exit;
    end;

    numDict[numbers[i]] := i;
  end;

  Result := new integer[0]; // Empty array indicates not found
end;

function DecimalToBase5(num: integer): string;
begin
  if num = 0 then
  begin
    Result := '0';
    exit;
  end;

  var digits := '01234';
  var n := Abs(num);
  var s := new StringBuilder;

  while n > 0 do
  begin
    s.Insert(0, digits[n mod 5 + 1]);
    n := n div 5;
  end;

  if num < 0 then
    s.Insert(0, '-');

  Result := s.ToString;
end;

function MinimumSum(num: integer): integer;
begin
  var digits := new List<integer>;
  var n := Abs(num);

  while n > 0 do
  begin
    digits.Add(n mod 10);
    n := n div 10;
  end;

  digits.Sort;

  if digits.Count < 4 then
  begin
    Result := -1;
    exit;
  end;

  var num1 := digits[0] * 10 + digits[2];
  var num2 := digits[1] * 10 + digits[3];

  Result := num1 + num2;
end;

function FindMostFrequentCharacter(s: string): char;
begin
  var charCount := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if charCount.ContainsKey(s[i]) then
      charCount[s[i]] += 1
    else
      charCount[s[i]] := 1;

  var maxCount := 0;
  var mostFrequentChar := s[1];

  foreach var kv in charCount do
    if kv.Value > maxCount then
    begin
      maxCount := kv.Value;
      mostFrequentChar := kv.Key;
    end;

  Result := mostFrequentChar;
end;

function KWeakestRows(mat: array of array of integer; k: integer): array of integer;
begin
  var m := mat.Length;
  var n := mat[0].Length;
  var strength := new List<integer>;
  var indices := new List<integer>;

  for var i := 0 to m - 1 do
  begin
    var count := 0;
    for var j := 0 to n - 1 do
      if mat[i][j] = 1 then
        count += 1;

    strength.Add(count);
    indices.Add(i);
  end;

  // Sort indices by strength
  var pairs := new List<(integer, integer)>;
  for var i := 0 to m - 1 do
    pairs.Add((strength[i], indices[i]));

  pairs.Sort((x, y) -> begin
    if x.Item1 <> y.Item1 then
       Result := x.Item1.CompareTo(y.Item1)
    else
      Result := x.Item2.CompareTo(y.Item2) end);

  var res := new List<integer>;
  for var i := 0 to k - 1 do
    res.Add(pairs[i].Item2);

  Result := res.ToArray;
end;

function FindSublistCount<T>(lst: array of T; sublist: array of T): integer;
begin
  var count := 0;

  for var i := 0 to lst.Length - sublist.Length do
  begin
    var &match := True;
    for var j := 0 to sublist.Length - 1 do
      if not lst[i + j].Equals(sublist[j]) then
      begin
        &match := False;
        break;
      end;

    if &match then
      count += 1;
  end;

  Result := count;
end;

function NumWaysToDecode(s: string): integer;
begin
  if (s.Length = 0) or (s[1] = '0') then
  begin
    Result := 0;
    exit;
  end;

  var n := s.Length;
  var dp := new integer[n + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
  begin
    var single := StrToInt(s.Substring(i-1, 1));
    var double_ := StrToInt(s.Substring(i-2, 2));

    if (single >= 1) and (single <= 9) then
      dp[i] += dp[i-1];

    if (double_ >= 10) and (double_ <= 26) then
      dp[i] += dp[i-2];
  end;

  Result := dp[n];
end;

function MaxLengthEqual(arr: array of integer): integer;
begin
  var count := 0;
  var maxLength := 0;
  var countMap := new Dictionary<integer, integer>;
  countMap[0] := -1;

  for var i := 0 to arr.Length - 1 do
  begin
    if arr[i] = 0 then
      count -= 1
    else
      count += 1;

    if countMap.ContainsKey(count) then
    begin
      var len := i - countMap[count];
      if len > maxLength then
        maxLength := len;
    end
    else
      countMap[count] := i;
  end;

