function WindowSum(nums: array of integer; k: integer): array of integer;
begin
  if (nums.Length = 0) or (k <= 0) or (nums.Length < k) then
  begin
    Result := new integer[0];
    exit;
  end;

  var ans := new List<integer>;
  var total := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    total += nums[i];

    if i >= k then
      total -= nums[i - k];

    if i >= k - 1 then
      ans.Add(total);
  end;

  Result := ans.ToArray;
end;

