  var minCost := 0;

  for var i := 0 to costs.Length - 1 do
  begin
    var acost := costs[i][0];
    var bcost := costs[i][1];
    ans.Add(bcost - acost);
    minCost += acost;
  end;

  ans.Sort;

  for var i := 0 to costs.Length div 2 - 1 do
    minCost += ans[i];

  Result := minCost;
end;

