function MinRotations(s: string): integer;
begin
  var n := s.Length;
  var rotations := 1;
  var temp := s;

  while rotations <= n do
  begin
    temp := temp.Substring(temp.Length - 1) + temp.Substring(0, temp.Length - 1);
    if temp = s then
    begin
      Result := rotations;
      exit;
    end;
    rotations += 1;
  end;

  Result := n;
end;

function ExchangeFirstLast(s: string): string;
begin
  if s.Length <= 1 then
  begin
    Result := s;
    exit;
  end;

  Result := s[s.Length] + s.Substring(1, s.Length - 2) + s[1];
end;

