function Factorial(n: integer): int64;
begin
  if (n = 0) or (n = 1) then
    Result := 1
  else
  begin
    Result := 1;
    for var i := 2 to n do
      Result *= i;
  end;
end;

function NumUniquePermutations(s: string): int64;
