  var count := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if count.ContainsKey(s[i]) then
      count[s[i]] += 1
    else
      count[s[i]] := 1;

  var total := Factorial(s.Length);

  foreach var kv in count do
    total := total div Factorial(kv.Value);

  Result := total;
end;

