function IsSumOfSquaresPerfectSquare(nums: array of integer): boolean;
begin
  var sumOfSquares: int64 := 0;

  foreach var num in nums do
    sumOfSquares += int64(num) * num;

  var root := Trunc(Sqrt(sumOfSquares));
  Result := root * root = sumOfSquares;
end;

