  for var i := 0 to islandGrid.Length - 1 do
    for var j := 0 to islandGrid[0].Length - 1 do
      if islandGrid[i][j] = 1 then
      begin
        DfsIsland(i, j);
        count += 1;
      end;

  Result := count;
end;

