function CountDistinctSubsequences(s: string): integer;
begin
  var MOD_ := 1000000007;
  var dp := new integer[s.Length + 1];
  dp[0] := 1;
  var last := new integer[26];
  for var i := 0 to 25 do
    last[i] := -1;

  for var i := 1 to s.Length do
  begin
    dp[i] := (2 * dp[i - 1]) mod MOD_;
    var idx := Ord(s[i]) - Ord('a');

    if last[idx] <> -1 then
    begin
      dp[i] := (dp[i] - dp[last[idx]] + MOD_) mod MOD_;
    end;

    last[idx] := i - 1;
  end;

  Result := (dp[s.Length] - 1) mod MOD_;
end;

function ThirdMax(nums: array of integer): integer;
begin
  var uniqueNums := (new HashSet<integer>(nums)).ToList;

  if uniqueNums.Count < 3 then
  begin
    Result := uniqueNums.Max;
    exit;
  end;

  uniqueNums.Sort;
  uniqueNums.Reverse;
  Result := uniqueNums[2];
end;

function CharCounter(str: string): Dictionary<char, integer>;
begin
  var charCount := new Dictionary<char, integer>;

  for var i := 1 to str.Length do
    if charCount.ContainsKey(str[i]) then
      charCount[str[i]] += 1
    else
      charCount[str[i]] := 1;

  Result := charCount;
end;

function MajorityElement(arr: array of integer): integer;
begin
  var count := 0;
  var candidate := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    if count = 0 then
    begin
      candidate := arr[i];
      count := 1;
    end
    else if candidate = arr[i] then
      count += 1
    else
      count -= 1;
  end;

  Result := candidate;
end;

function StrictlyAscending(lst: array of integer): boolean;
begin
  for var i := 0 to lst.Length - 2 do
    if lst[i] >= lst[i + 1] then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;

function KnightDialer(n: integer): int64;
begin
  var directions := |(2, 1), (1, 2), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2)|;
  var r := 4;
  var c := 3;
  var dp := new int64[r, c];
  var dpNext := new int64[r, c];
  var MOD_ := Round(Power(10, 9) + 7);

  for var i := 0 to r - 1 do
    for var j := 0 to c - 1 do
    begin
      dp[i, j] := 1;
      dpNext[i, j] := 1;
    end;

  var forbid := new HashSet<(integer, integer)>;
  forbid.Add((3, 0));
  forbid.Add((3, 2));

  for var step := 2 to n do
  begin
    // Swap dp and dpNext
    var temp := dp;
    dp := dpNext;
    dpNext := temp;

    for var i := 0 to r - 1 do
      for var j := 0 to c - 1 do
      begin
        if forbid.Contains((i, j)) then
          continue;

        var curJumps: int64 := 0;

        foreach var (di, dj) in directions do
        begin
          var ti := i + di;
          var tj := j + dj;

          if (ti >= 0) and (ti < r) and (tj >= 0) and (tj < c) and not forbid.Contains((ti, tj)) then
            curJumps := (curJumps + dp[ti, tj]) mod MOD_;
        end;

        dpNext[i, j] := curJumps;
      end;
  end;

  var total: int64 := 0;
  for var i := 0 to r - 1 do
    for var j := 0 to c - 1 do
      if not forbid.Contains((i, j)) then
        total := (total + dpNext[i, j]) mod MOD_;

  Result := total;
end;

function IsDivisibleIntoConsecutiveSubsequences(nums: array of integer): boolean;
begin
  var count := new Dictionary<integer, integer>;

  foreach var num in nums do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;

  var starts := new HashSet<integer>;

  foreach var num in count.Keys do
    if not count.ContainsKey(num - 1) then
      starts.Add(num);

  foreach var start in starts do
  begin
    var val := start;
    while count.ContainsKey(val) and (count[val] > 0) do
    begin
      count[val] -= 1;
      val += 1;

      if (count.ContainsKey(val)) and (count[val] = 0) and (val - start < 3) then
      begin
        Result := False;
        exit;
      end;
    end;
  end;

  Result := True;
end;

function MaxNestedDepth(lst: array of object): integer;
begin
  var depth := 1;

  for var i := 0 to lst.Length - 1 do
  begin
    if lst[i] is array of object then
    begin
      var subDepth := 1 + MaxNestedDepth(lst[i] as array of object);
      if subDepth > depth then
        depth := subDepth;
    end;
  end;

  Result := depth;
end;

function IsPalindromeAlpha(s: string): boolean;
begin
  // Check if all characters are alphabets
  for var i := 1 to s.Length do
    if not Char.IsLetter(s[i]) then
    begin
      Result := False;
      exit;
    end;

  Result := s = s.Inverse;
end;

function LongestUniqueSubarray(nums: array of integer): integer;
begin
  var start := 0;
  var maxLength := 0;
  var seen := new Dictionary<integer, integer>;

  for var i := 0 to nums.Length - 1 do
  begin
    if seen.ContainsKey(nums[i]) and (start <= seen[nums[i]]) then
      start := seen[nums[i]] + 1
    else
    begin
      var len := i - start + 1;
      if len > maxLength then
        maxLength := len;
    end;

    seen[nums[i]] := i;
  end;

  Result := maxLength;
end;

function MinSubsequence(nums: array of integer): array of integer;
begin
  var subsequence := new List<integer>;
  var sorted := nums.ToArray;
  sorted.Sort;
  sorted := sorted.Reverse.ToArray;

  for var i := 0 to sorted.Length - 1 do
  begin
    subsequence.Add(sorted[i]);
    var sumSubseq := subsequence.Sum;
    var remainingSum := sorted.Skip(i + 1).Sum;

    if sumSubseq > remainingSum then
      break;
  end;

  Result := subsequence.ToArray;
end;

function MinFlipsAlternating(s: string): integer;
begin
  var count1 := 0;  // Count of flips required to make string starting with '1'
  var count2 := 0;  // Count of flips required to make string starting with '0'

  for var i := 1 to s.Length do
  begin
    if i mod 2 = 1 then  // odd position (1-indexed)
    begin
      if s[i] = '1' then
        count1 += 1
      else
        count2 += 1;
    end
    else  // even position
    begin
      if s[i] = '1' then
        count2 += 1
      else
        count1 += 1;
    end;
  end;

  Result := Min(count1, count2);
end;

function IncrementByIndex(lst: array of integer): array of integer;
begin
  var incremented := new integer[lst.Length];

  for var i := 0 to lst.Length - 1 do
    incremented[i] := lst[i] + i;

  Result := incremented;
end;

function IsStrictBinary(seq: string): boolean;
begin
  if seq.Length = 0 then
  begin
    Result := False;
    exit;
  end;

  if (seq[1] = '0') and (seq.Length > 1) then
  begin
    Result := False;
    exit;
  end;

  for var i := 1 to seq.Length do
    if (seq[i] <> '0') and (seq[i] <> '1') then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;

function PalindromeSubstring(s: string): string;
begin
  if s.Length = 1 then
  begin
    Result := s;
    exit;
  end;

  var longest := '';

  for var i := 1 to s.Length do
  begin
    // odd length palindromes
    var left := i;
    var right := i;

    while (left >= 1) and (right <= s.Length) and (s[left] = s[right]) do
    begin
      var len := right - left + 1;
      if len > longest.Length then
        longest := s.Substring(left - 1, len);
      left -= 1;
      right += 1;
    end;

    // even length palindromes
    left := i;
    right := i + 1;

    while (left >= 1) and (right <= s.Length) and (s[left] = s[right]) do
    begin
      var len := right - left + 1;
      if len > longest.Length then
        longest := s.Substring(left - 1, len);
      left -= 1;
      right += 1;
    end;
  end;

  Result := longest;
end;

var memoBST: Dictionary<integer, int64>;

function DfsBST(nodes: integer): int64;
begin
  if nodes <= 1 then
  begin
    Result := 1;
    exit;
  end;

  if memoBST.ContainsKey(nodes) then
  begin
    Result := memoBST[nodes];
    exit;
  end;

  var count: int64 := 0;

  for var root := 1 to nodes do
  begin
    var leftSubtrees := DfsBST(root - 1);
    var rightSubtrees := DfsBST(nodes - root);
    count += leftSubtrees * rightSubtrees;
  end;

  memoBST[nodes] := count;
  Result := count;
end;

function NumUniqueBST(n: integer): int64;
begin
  memoBST := new Dictionary<integer, int64>;
  Result := DfsBST(n);
end;

