function MyAtoi(str: string): integer;
begin
  var s := str.TrimStart;

  if s.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var startIdx := 1;

  if s[1] = '-' then
  begin
    sign := -1;
    startIdx := 2;
  end
  else if s[1] = '+' then
    startIdx := 2;

  var value: int64 := 0;

  for var i := startIdx to s.Length do
  begin
    if not Char.IsDigit(s[i]) then
      break;

    value := value * 10 + (Ord(s[i]) - Ord('0'));

    if sign * value > int64(2147483647) then
    begin
      Result := 2147483647;
      exit;
    end;

    if sign * value < int64(-2147483648) then
    begin
      Result := -2147483648;
      exit;
    end;
  end;

  Result := integer(sign * value);
end;

function ShortestPathAllKeys(grid: array of string): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var queue := new Queue<(integer, integer, integer, integer)>;
  var numOfKeys := 0;
  var keys := new Dictionary<char, integer>;

  for var ch := 'a' to 'f' do
    keys[ch] := Ord(ch) - Ord('a');

  var locks := new Dictionary<char, integer>;
  for var ch := 'A' to 'F' do
    locks[ch] := Ord(ch) - Ord('A');

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if grid[i][j+1] = '@' then
        queue.Enqueue((i, j, 0, 0));

      if (grid[i][j+1] >= 'a') and (grid[i][j+1] <= 'f') then
        numOfKeys += 1;
    end;

  var visited := new HashSet<(integer, integer, integer)>;

  while queue.Count > 0 do
  begin
    var (i, j, found, steps) := queue.Dequeue;
    var curr := grid[i][j+1];

    if ((curr >= 'A') and (curr <= 'F')) and (((found shr locks[curr]) and 1) = 0) then
      continue;

    if curr = '#' then
      continue;

    if (curr >= 'a') and (curr <= 'f') then
    begin
      var newFound := found or (1 shl keys[curr]);
      if newFound = (1 shl numOfKeys) - 1 then
      begin
        Result := steps;
        exit;
      end;
      found := newFound;
    end;

    var dirs := |(1, 0), (0, 1), (-1, 0), (0, -1)|;

    foreach var (di, dj) in dirs do
    begin
      var ni := i + di;
      var nj := j + dj;

      if (ni >= 0) and (ni < m) and (nj >= 0) and (nj < n) and 
         not visited.Contains((ni, nj, found)) then
      begin
        visited.Add((ni, nj, found));
        queue.Enqueue((ni, nj, found, steps + 1));
      end;
    end;
  end;

  Result := -1;
end;

function FindLargestDivisibleBy3(lst: array of integer): integer?;
begin
  var maxDivisible: integer? := nil;

  foreach var num in lst do
    if (num mod 3 = 0) and ((not maxDivisible.HasValue) or (num > maxDivisible.Value)) then
      maxDivisible := num;

  Result := maxDivisible;
end;

function IsPalindromeIgnoreSpecial(s: string): boolean;
begin
  var cleaned := new StringBuilder;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    if Char.IsLetterOrDigit(ch) then
      cleaned.Append(Char.ToLower(ch));
  end;

  var cleanedStr := cleaned.ToString;
  Result := cleanedStr = cleanedStr.Inverse;
end;

function MaxBinaryTree(tree: array of integer?): integer?;
begin
  if tree.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var maxVal := tree[0];

  for var i := 1 to tree.Length - 1 do
    if tree[i].HasValue and ((not maxVal.HasValue) or (tree[i].Value > maxVal.Value)) then
      maxVal := tree[i];

  Result := maxVal;
end;

function MaxPalindromeSubseq(s: string): integer;
begin
  var n := s.Length;
  var dp := new integer[n, n];

  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 1;
    for var j := i + 1 to n - 1 do
    begin
      if s[i+1] = s[j+1] then
        dp[i, j] := dp[i+1, j-1] + 2
      else
        dp[i, j] := Max(dp[i+1, j], dp[i, j-1]);
    end;
  end;

  if n = 0 then
    Result := 0
  else
    Result := dp[0, n-1];
end;

function IsSameRow(word: string): boolean;
begin
  var row1 := new HashSet<char>('qwertyuiop'.ToCharArray);
  var row2 := new HashSet<char>('asdfghjkl'.ToCharArray);
  var row3 := new HashSet<char>('zxcvbnm'.ToCharArray);

  var wordSet := word.ToLower.ToHashSet;
  Result := wordSet.IsSubsetOf(row1) or wordSet.IsSubsetOf(row2) or wordSet.IsSubsetOf(row3);
end;

function FindWords(words: array of string): array of string;
begin
  var singleRowWords := new List<string>;

  foreach var word in words do
    if IsSameRow(word) then
      singleRowWords.Add(word);

  Result := singleRowWords.ToArray;
end;

function ReverseStringList(inputString: string): array of char;
begin
  var charList := inputString.ToCharArray;
  var start := 0;
  var &end := charList.Length - 1;

  while start < &end do
  begin
    var temp := charList[start];
    charList[start] := charList[&end];
    charList[&end] := temp;
    start += 1;
    &end -= 1;
  end;

  Result := charList;
end;

function SecLarge(numbers: array of integer): integer?;
begin
  if numbers.Length < 2 then
  begin
    Result := nil;
    exit;
  end;

  var uniqueNums := (new HashSet<integer>(numbers)).ToList;

  if uniqueNums.Count < 2 then
  begin
    Result := nil;
    exit;
  end;

  uniqueNums.Sort;
  Result := uniqueNums[uniqueNums.Count - 2];
end;

function CountPatternRecursively(str, pattern: string): integer;
begin
  if str.Length < pattern.Length then
  begin
    Result := 0;
    exit;
  end;

  if str.Substring(0, pattern.Length) = pattern then
    Result := 1 + CountPatternRecursively(str.Substring(pattern.Length), pattern)
  else
    Result := CountPatternRecursively(str.Substring(1), pattern);
end;

function GridTraversal(m, n: integer): int64;
begin
  var dp := new int64[n + 1];

  for var i := 1 to m do
    for var j := 1 to n do
      if (i = 1) and (j = 1) then
        dp[j] := 1
      else
        dp[j] := dp[j] + dp[j - 1];

  Result := dp[n];
end;

function FindPowerOfTwo(lst: array of integer): integer;
begin
  var maxPower := -1;

  foreach var x in lst do
  begin
    // Check if x is a power of two
    if (x > 0) and ((x and (x - 1)) = 0) then
      if x > maxPower then
        maxPower := x;
  end;

  Result := maxPower;
end;

function WordLengths(words: array of string): Dictionary<string, integer>;
begin
  var dict := new Dictionary<string, integer>;

  foreach var word in words do
    dict[word] := word.Length;

  Result := dict;
end;

function FindPairForSum(numbers: array of integer; target: integer; var found: boolean): (integer, integer);
begin
  var numDict := new Dictionary<integer, integer>;
  found := false;

  for var i := 0 to numbers.Length - 1 do
  begin
    var complement := target - numbers[i];

    if numDict.ContainsKey(complement) then
    begin
      Result := (numDict[complement], i);
      found := true;
      exit;
    end;

    numDict[numbers[i]] := i;
  end;

  Result := (-1, -1);
end;

function PascalsTriangle(n: integer): array of array of integer;
begin
  var triangle := new List<array of integer>;

  for var i := 0 to n - 1 do
  begin
    var row := new List<integer>;

    for var j := 0 to i do
    begin
      if (j = 0) or (j = i) then
        row.Add(1)
      else
      begin
        var prevRow := triangle[i-1];
        row.Add(prevRow[j-1] + prevRow[j]);
      end;
    end;

    triangle.Add(row.ToArray);
  end;

  Result := triangle.ToArray;
end;

function SmallestSubstringWithPattern(str1, pattern: string): string;
begin
  var windowStart := 1;
  var matched := 0;
  var charFrequency := new Dictionary<char, integer>;

  for var i := 1 to pattern.Length do
    if charFrequency.ContainsKey(pattern[i]) then
      charFrequency[pattern[i]] += 1
    else
      charFrequency[pattern[i]] := 1;

  var strMinLength := str1.Length + 1;
  var subStr := '';

  for var windowEnd := 1 to str1.Length do
  begin
    var rightChar := str1[windowEnd];

    if charFrequency.ContainsKey(rightChar) then
    begin
      charFrequency[rightChar] -= 1;
      if charFrequency[rightChar] >= 0 then
        matched += 1;
    end;

    while matched = pattern.Length do
    begin
      var currentLength := windowEnd - windowStart + 1;

      if currentLength < strMinLength then
      begin
        strMinLength := currentLength;
        subStr := str1.Substring(windowStart - 1, currentLength);
      end;

      var leftChar := str1[windowStart];
      windowStart += 1;

      if charFrequency.ContainsKey(leftChar) then
      begin
        if charFrequency[leftChar] = 0 then
          matched -= 1;
        charFrequency[leftChar] += 1;
      end;
    end;
  end;

  Result := subStr;
end;

function SmallestRepeatingSeq(s: string): string;
begin
  var length := s.Length;

  for var i := 1 to length div 2 do
  begin
    if length mod i = 0 then
    begin
      var pattern := s.Substring(0, i);
      var repeated := '';

      for var j := 1 to length div i do
        repeated += pattern;

      if repeated = s then
      begin
        Result := pattern;
        exit;
      end;
    end;
  end;

  Result := s;
end;

function FindUniquePaths(m, n: integer): integer;
begin
  var dp := new integer[m, n];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if (i = 0) or (j = 0) then
        dp[i, j] := 1
      else
        dp[i, j] := dp[i-1, j] + dp[i, j-1];

  Result := dp[m-1, n-1];
end;

function PalindromeList(lst: array of string): boolean;
begin
  var left := 0;
  var right := lst.Length - 1;

  while left < right do
  begin
    if lst[left] <> lst[right] then
    begin
      Result := False;
      exit;
    end;
    left += 1;
    right -= 1;
  end;

  Result := True;
end;

function MaxPositiveSubarraySum(arr: array of integer): integer;
begin
  var maxSum := 0;
  var currentSum := 0;
  var hasPositive := False;

  foreach var num in arr do
  begin
    if num > 0 then
      hasPositive := True;

    currentSum += num;

    if currentSum < 0 then
      currentSum := 0;

    if currentSum > maxSum then
      maxSum := currentSum;
  end;

  if hasPositive then
    Result := maxSum
  else
    Result := 0;
end;

