function CanPartition(nums: array of integer): boolean;
begin
  var total := nums.Sum;

  if total mod 2 <> 0 then
  begin
    Result := False;
    exit;
  end;

  var target := total div 2;
  var sums := new HashSet<integer>;
  sums.Add(0);

  foreach var n in nums do
  begin
    var newSums := new HashSet<integer>;

    foreach var el in sums do
    begin
      if el + n = target then
      begin
        Result := True;
        exit;
      end;
      newSums.Add(el);
      newSums.Add(el + n);
    end;

    sums := newSums;
  end;

  Result := False;
end;

function HasArithmeticSlice(A: array of integer): boolean;
begin
  if A.Length < 3 then
  begin
    Result := False;
    exit;
  end;

  var diff := A[1] - A[0];
  var count := 2;

  for var i := 2 to A.Length - 1 do
  begin
    if A[i] - A[i-1] = diff then
    begin
      count += 1;
      if count >= 3 then
      begin
        Result := True;
        exit;
      end;
    end
    else
    begin
      if count >= 3 then
      begin
        Result := True;
        exit;
      end;
      diff := A[i] - A[i-1];
      count := 2;
    end;
  end;

  Result := count >= 3;
end;

