  foreach var n in nums do
  begin
    if not numSet.Contains(n - 1) then
    begin
      var length := 0;
      while numSet.Contains(n + length) do
        length += 1;

      if length > longest then
        longest := length;
    end;
  end;

  Result := longest;
end;

