function VersionCompare(version1, version2: string): integer;
begin
  var parts1 := version1.Split('.');
  var parts2 := version2.Split('.');
  var maxLen := Max(parts1.Length, parts2.Length);

  for var i := 0 to maxLen - 1 do
  begin
    var v1 := 0;
    var v2 := 0;

    if i < parts1.Length then
      v1 := StrToInt(parts1[i]);

    if i < parts2.Length then
      v2 := StrToInt(parts2[i]);

    if v1 <> v2 then
    begin
      if v1 > v2 then
        Result := 1
      else
        Result := -1;
      exit;
    end;
  end;

  Result := 0;
end;

function GCD(a, b: integer): integer;
begin
  while b <> 0 do
  begin
    var temp := b;
    b := a mod b;
    a := temp;
  end;
  Result := a;
end;

function FindLCM(num1, num2: integer): integer;
begin
  Result := (num1 div GCD(num1, num2)) * num2;
end;

function CountValidParenthesesStrings(n: integer): int64;
begin
  if n = 0 then
  begin
    Result := 1;
    exit;
  end;

  var count := new int64[n + 1];
  count[0] := 1;

  for var i := 1 to n do
    for var j := 0 to i - 1 do
      count[i] := count[i] + count[j] * count[i - 1 - j];

  Result := count[n];
end;

function FindNextGreaterElements(nums: array of integer): array of integer;
begin
  var stack := new Stack<integer>;
  var nextGreater := new integer[nums.Length];

  for var i := 0 to nextGreater.Length - 1 do
    nextGreater[i] := -1;

  for var i := 0 to nums.Length - 1 do
  begin
    while (stack.Count > 0) and (nums[stack.Peek] < nums[i]) do
    begin
      var index := stack.Pop;
      nextGreater[index] := nums[i];
    end;
    stack.Push(i);
  end;

  Result := nextGreater;
end;

function LongestKSubstring(s: string; k: integer): integer;
begin
  var n := s.Length;
  var ans := -1;
  var charMap := new Dictionary<char, integer>;
  var j := 1;

  for var i := 1 to n do
  begin
    if charMap.ContainsKey(s[i]) then
      charMap[s[i]] += 1
    else
      charMap[s[i]] := 1;

    if charMap.Count = k then
    begin
      var len := i - j + 1;
      if len > ans then
        ans := len;
    end;

    while charMap.Count > k do
    begin
      charMap[s[j]] -= 1;

      if charMap[s[j]] = 0 then
        charMap.Remove(s[j]);

      j += 1;
    end;

    if charMap.Count = k then
    begin
      var len := i - j + 1;
      if len > ans then
        ans := len;
    end;
  end;

  Result := ans;
end;

function MinDistance(arr: array of integer; x: integer): integer;
begin
  var n := arr.Length;
  var minDist := n;
  var prev := -1;

  for var i := 0 to n - 1 do
  begin
    if arr[i] = x then
    begin
      if prev <> -1 then
      begin
        var dist := i - prev;
        if dist < minDist then
          minDist := dist;
      end;
      prev := i;
    end;
  end;

  if minDist = n then
    Result := -1
  else
    Result := minDist;
end;

function ArraysIntersection(arr1, arr2, arr3: array of integer): array of integer;
begin
  if (arr1.Length = 0) or (arr2.Length = 0) or (arr3.Length = 0) then
  begin
    Result := new integer[0];
    exit;
  end;

  var i := 0;
  var j := 0;
  var k := 0;
  var intersection := new List<integer>;

  while (i < arr1.Length) and (j < arr2.Length) and (k < arr3.Length) do
  begin
    if (arr1[i] = arr2[j]) and (arr2[j] = arr3[k]) then
    begin
      if (intersection.Count = 0) or (intersection.Last <> arr1[i]) then
        intersection.Add(arr1[i]);
      i += 1;
      j += 1;
      k += 1;
    end
    else
    begin
      var maxVal := Max(Max(arr1[i], arr2[j]), arr3[k]);

      if arr1[i] < maxVal then i += 1;
      if arr2[j] < maxVal then j += 1;
      if arr3[k] < maxVal then k += 1;
    end;
  end;

  Result := intersection.ToArray;
end;

