function NthFibMultipleOf3(n: integer): int64;
begin
  var a: int64 := 0;
  var b: int64 := 1;
  var count := 0;

  while True do
  begin
    var c := a + b;
    a := b;
    b := c;

    if b mod 3 = 0 then
    begin
      count += 1;
      if count = n then
      begin
        Result := b;
        exit;
      end;
    end;
  end;
end;

