  begin
    var targetPos := alpha.IndexOf(word[i]);
    var d1 := Abs(targetPos - currentPos);
    var d2 := 26 - d1;
    var move := Min(d1, d2);
    count := count + move + 1; // +1 for typing the letter
    currentPos := targetPos;
  end;

  Result := count;
end;

