  var score := 0;
  var stack := new Stack<integer>;

  for var i := 1 to s.Length do
  begin
    if s[i] = '(' then
    begin
      stack.Push(score);
      score := 0;
    end
    else // s[i] = ')'
    begin
      score := stack.Pop + Max(score * 2, 1);
    end;
  end;

  Result := score;
end;

