  var pos := k + 1;

  while pos <> 1 do
  begin
    if (pos and 1) = 0 then
      digits.Add('4')
    else
      digits.Add('7');
    pos := pos shr 1;
  end;

  digits.Reverse;
  Result := string.Join('', digits);
end;

function SmallestSubWithSum(arr: array of integer; x: integer): integer;
begin
  var n := arr.Length;
  var minLen := n + 1;
  var currSum := 0;
  var start := 0;

  for var &end := 0 to n - 1 do
  begin
    currSum += arr[&end];

    while currSum >= x do
    begin
      var len := &end - start + 1;
      if len < minLen then
        minLen := len;

      currSum -= arr[start];
      start += 1;
    end;
  end;

  if minLen <= n then
    Result := minLen
  else
    Result := 0;
end;

