function Dfs(graph: Dictionary<integer, List<integer>>; v: integer; visited: HashSet<integer>; destination: integer): boolean;
begin
  visited.Add(v);

  if v = destination then
  begin
    Result := True;
    exit;
  end;

  if graph.ContainsKey(v) then
  begin
    foreach var neighbor in graph[v] do
    begin
      if not visited.Contains(neighbor) then
      begin
        if Dfs(graph, neighbor, visited, destination) then
        begin
          Result := True;
          exit;
        end;
      end;
    end;
  end;

  Result := False;
end;

function HasPath(n: integer; edges: array of array of integer; source, destination: integer): boolean;
begin
  var graph := new Dictionary<integer, List<integer>>;

  foreach var edge in edges do
  begin
    var u := edge[0];
    var v := edge[1];

    if not graph.ContainsKey(u) then
      graph[u] := new List<integer>;
    if not graph.ContainsKey(v) then
      graph[v] := new List<integer>;

    graph[u].Add(v);
    graph[v].Add(u);
  end;

  var visited := new HashSet<integer>;
  Result := Dfs(graph, source, visited, destination);
end;

function AddComplexNumbers(a, b: string): string;
begin
  var aParts := a.Split('+');
  var bParts := b.Split('+');

  var a1 := StrToInt(aParts[0]);
  var a2 := StrToInt(aParts[1].Substring(0, aParts[1].Length - 1));
  var b1 := StrToInt(bParts[0]);
  var b2 := StrToInt(bParts[1].Substring(0, bParts[1].Length - 1));

  var realPart := a1 + b1;
  var imaginaryPart := a2 + b2;

  Result := realPart.ToString + '+' + imaginaryPart.ToString + 'i';
end;

function UniqueWays(n: integer): int64;
begin
  if n < 0 then
  begin
    Result := 0;
    exit;
  end;

  var dp := new int64[n + 1];
  dp[0] := 1;

  for var i := 1 to n do
  begin
    if i >= 1 then dp[i] += dp[i - 1];
    if i >= 3 then dp[i] += dp[i - 3];
    if i >= 4 then dp[i] += dp[i - 4];
  end;

  Result := dp[n];
end;

