  if password.Length < 8 then
  begin
    Result := False;
    exit;
  end;

  var hasLower := False;
  var hasUpper := False;
  var hasDigit := False;
  var hasSpecial := False;
  var specialChars := new HashSet<char>('!@#$%^&*'.ToCharArray);

  for var i := 1 to password.Length do
  begin
    var ch := password[i];

    if Char.IsLower(ch) then
      hasLower := True
    else if Char.IsUpper(ch) then
      hasUpper := True
    else if Char.IsDigit(ch) then
      hasDigit := True
    else if specialChars.Contains(ch) then
      hasSpecial := True;
  end;

