function CheckSubarraySum(nums: array of integer; k: integer): boolean;
begin
  var remInd := new Dictionary<integer, integer>;
  remInd[0] := -1;
  var curSum := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    curSum += nums[i];
    var remainder := curSum mod k;

    if not remInd.ContainsKey(remainder) then
      remInd[remainder] := i
    else if i - remInd[remainder] > 1 then
    begin
      Result := True;
      exit;
    end;
  end;

  Result := False;
end;

function DiagonalOrder(mat: array of array of integer): array of integer;
begin
  var m := mat.Length;
  var n := mat[0].Length;
  var diagonal := new List<integer>;

  for var i := 0 to m + n - 2 do
  begin
    if i mod 2 = 0 then
    begin
      var row := Max(0, i - n + 1);
      var col := i - row;
      while (row < m) and (col >= 0) do
      begin
        diagonal.Add(mat[row][col]);
        row += 1;
        col -= 1;
      end;
    end
    else
    begin
      var col := Min(i, n - 1);
      var row := i - col;
      while (col >= 0) and (row < m) do
      begin
        diagonal.Add(mat[row][col]);
        col -= 1;
        row += 1;
      end;
    end;
  end;

  Result := diagonal.ToArray;
end;

