  foreach var word in words1 do
    if counter1.ContainsKey(word) then
      counter1[word] += 1
    else
      counter1[word] := 1;

  foreach var word in words2 do
    if counter2.ContainsKey(word) then
      counter2[word] += 1
    else
      counter2[word] := 1;

  var commonWords := new HashSet<string>;

  foreach var kv in counter1 do
    if (kv.Value = 1) and counter2.ContainsKey(kv.Key) and (counter2[kv.Key] = 1) then
      commonWords.Add(kv.Key);

  Result := commonWords.Count;
end;

