function ClimbStaircase(n: integer): int64;
begin
  if (n = 0) or (n = 1) then
  begin
    Result := 1;
    exit;
  end;

  if n = 2 then
  begin
    Result := 2;
    exit;
  end;

  var dp := new int64[n + 1];
  dp[0] := 1;
  dp[1] := 1;
  dp[2] := 2;

  for var i := 3 to n do
    dp[i] := dp[i-1] + dp[i-2] + dp[i-3];

  Result := dp[n];
end;

function LongestSubstringWithRepeatedChars(s: string): string;
begin
  var maxSubstring := '';
  var currentSubstring := '';
  var prevChar := #0;
  var charCount := 0;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];

    if ch = prevChar then
    begin
      charCount += 1;
      if charCount > 2 then
      begin
        if currentSubstring.Length > maxSubstring.Length then
          maxSubstring := currentSubstring;
        currentSubstring := new string(prevChar, 2);
        charCount := 1;
      end
      else
        currentSubstring += ch;
    end
    else
    begin
      if currentSubstring.Length > maxSubstring.Length then
        maxSubstring := currentSubstring;
      currentSubstring := ch.ToString;
      prevChar := ch;
      charCount := 1;
    end;
  end;

  if currentSubstring.Length > maxSubstring.Length then
    maxSubstring := currentSubstring;

  Result := maxSubstring;
end;

