function NumUniqueBSTs(n: integer): int64;
begin
  if n <= 1 then
  begin
    Result := 1;
    exit;
  end;

  var G := new int64[n + 1];
  G[0] := 1;
  G[1] := 1;
  G[2] := 2;

  for var i := 3 to n do
  begin
    G[i] := 0;
    for var k := 0 to i - 1 do
      G[i] := G[i] + G[k] * G[i - k - 1];
  end;

  Result := G[n];
end;

function Sum67(nums: array of integer): integer;
