function GCD(x, y: integer): integer;
begin
  var a := x;
  var b := y;
  while b <> 0 do
  begin
    var temp := b;
    b := a mod b;
    a := temp;
  end;
  Result := a;
end;

function GCDArray(nlist: array of integer): integer;
