  var hasUpper := False;
  var hasDigit := False;

  for var i := 1 to password.Length do
  begin
    var ch := password[i];
    if Char.IsLower(ch) then
      hasLower := True
    else if Char.IsUpper(ch) then
      hasUpper := True
    else if Char.IsDigit(ch) then
      hasDigit := True;
  end;

  Result := hasLower and hasUpper and hasDigit;
end;

