function SumOfDigitsBase3(n: integer): integer;
begin
  var answer := 0;
  var num := n;

  while num > 0 do
  begin
    answer := answer + (num mod 3);
    num := num div 3;
  end;

  Result := answer;
end;

function CalculateMinMoves(brackets: string): integer;
