function LongestHarmoniousSubsequence(nums: array of integer): integer;
begin
  var sorted := nums.ToArray;
  sorted.Sort;
  var maxLen := 0;
  var start := 0;

  for var i := 0 to sorted.Length - 1 do
  begin
    while sorted[i] - sorted[start] > 1 do
      start := start + 1;

    if sorted[i] - sorted[start] = 1 then
    begin
      var len := i - start + 1;
      if len > maxLen then
        maxLen := len;
    end;
  end;

  Result := maxLen;
end;

