  var start := -1;
  var &end := -1;

  for var i := 0 to nums.Length - 1 do
    if nums[i] <> sortedNums[i] then
    begin
      if start = -1 then
        start := i;
      &end := i;
    end;

  if start = -1 then
    Result := 0
  else
    Result := &end - start + 1;
end;

function MinJump(arr: array of integer): integer;
begin
  var n := arr.Length;
  if (n = 0) or (arr[0] = 0) then
  begin
    Result := MaxInt;
    exit;
  end;

  var jumps := new integer[n];
  jumps[0] := 0;

  for var i := 1 to n - 1 do
  begin
    jumps[i] := MaxInt;
    for var j := 0 to i - 1 do
    begin
      if (i <= j + arr[j]) and (jumps[j] <> MaxInt) then
      begin
        jumps[i] := Min(jumps[i], jumps[j] + 1);
        break;
      end;
    end;
  end;

  Result := jumps[n - 1];
end;

function SumTwoLargestNums(lst: array of integer): integer;
begin
  var sorted := lst.OrderBy(x -> x).ToArray;
