var combinationsListResult: List<array of integer>;
    combinationsListSource: array of integer;
    combinationsListN: integer;

procedure GenerateCombinations(start: integer; current: List<integer>);
begin
  if current.Count = combinationsListN then
  begin
    combinationsListResult.Add(current.ToArray);
    exit;
  end;

  for var i := start to combinationsListSource.Length - 1 do
  begin
    current.Add(combinationsListSource[i]);
    GenerateCombinations(i + 1, current);
    current.RemoveAt(current.Count - 1);
  end;
end;

