  begin
    var dp := new integer[n + 1];
    dp[0] := 1;
    dp[1] := 1;
    dp[2] := 2;
    dp[3] := 4;

    for var i := 4 to n do
      dp[i] := dp[i - 1] + dp[i - 2] + dp[i - 3];

    Result := dp[n];
  end;
end;

function MaxSumLessThanK(A: array of integer; K: integer): integer;
begin
  if A.Length = 0 then
  begin
    Result := -1;
    exit;
  end;

  var sorted := A.OrderBy(x -> x).ToArray;
  var left := 0;
  var right := sorted.Length - 1;
  var res := -1;

  while left < right do
  begin
    var tmp := sorted[left] + sorted[right];
    if tmp > K then
      right -= 1
    else
    begin
      if tmp > res then
        res := tmp;
      left += 1;
    end;
  end;

  Result := res;
end;

