  var minDiff := MaxInt;

  for var i := 1 to sorted.Length - 1 do
  begin
    var diff := Abs(sorted[i] - sorted[i - 1]);
    if diff < minDiff then
      minDiff := diff;
  end;

  Result := minDiff;
end;

function LIS(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var n := nums.Length;
  var dp := ArrGen(n, i -> 1);

  for var i := 1 to n - 1 do
    for var j := 0 to i - 1 do
      if (nums[i] > nums[j]) and (dp[i] < dp[j] + 1) then
        dp[i] := dp[j] + 1;

  Result := dp.Max;
end;

function FindNextPowerOf2(n: integer): integer;
begin
  if n = 0 then
    Result := 1
  else if (n and (n - 1)) = 0 then
    Result := -1
  else
  begin
    var bitLength := 0;
    var temp := n;
    while temp > 0 do
    begin
      temp := temp shr 1;
      bitLength += 1;
    end;
    Result := 1 shl bitLength;
  end;
end;

function LastOccurrence(nums: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;
  var idx := -1;

  while left <= right do
  begin
    var mid := left + (right - left) div 2;

    if nums[mid] = target then
    begin
      idx := mid;
      left := mid + 1;
    end
    else if nums[mid] < target then
      left := mid + 1
    else
      right := mid - 1;
  end;

  Result := idx;
end;

