function MissingPositive(nums: array of integer): integer;
begin
  var n := nums.Length;
  var arr := nums.Copy;

  for var i := 0 to n - 1 do
  begin
    while (1 <= arr[i]) and (arr[i] <= n) and (arr[arr[i] - 1] <> arr[i]) do
      Swap(arr[arr[i] - 1], arr[i]);
  end;

  for var i := 0 to n - 1 do
    if arr[i] <> i + 1 then
    begin
      Result := i + 1;
      exit;
    end;

  Result := n + 1;
end;

function DailyTemperatures(T: array of integer): array of integer;
begin
  var ans := new integer[T.Length];

  for var i := T.Length - 2 downto 0 do
  begin
    var nxt := i + 1;
    while T[i] >= T[nxt] do
    begin
      if ans[nxt] = 0 then
        break;
      nxt += ans[nxt];
    end;
    if T[nxt] > T[i] then
      ans[i] := nxt - i;
  end;

  Result := ans;
end;

function EvenFibonacciSum(limit: integer): integer;
begin
  var a := 1;
  var b := 2;
  var evenSum := 0;

  while b <= limit do
  begin
    if b mod 2 = 0 then
      evenSum += b;
    (a, b) := (b, a + b);
  end;

  Result := evenSum;
end;

function LengthOfLongestSubstringThreeDistinct(s: string): integer;
begin
  var maxLen := 0;
  var chars := new Dictionary<char, integer>;
  var start := 0;

  for var i := 0 to s.Length - 1 do
  begin
    var c := s[i + 1];
    if chars.ContainsKey(c) then
      chars[c] += 1
    else
      chars[c] := 1;

    while chars.Count > 3 do
    begin
      var startChar := s[start + 1];
      chars[startChar] -= 1;
      if chars[startChar] = 0 then
        chars.Remove(startChar);
      start += 1;
    end;

    maxLen := max(maxLen, i - start + 1);
  end;

  Result := maxLen;
end;

function ValidParenthesesString(s: string): boolean;
begin
  var lo := 0;
  var hi := 0;

  foreach var c in s do
  begin
    if c = '(' then
    begin
      lo += 1;
      hi += 1;
    end
    else if c = ')' then
    begin
      lo := max(lo - 1, 0);
      hi -= 1;
    end
    else // c = '*'
    begin
      lo := max(lo - 1, 0);
      hi += 1;
    end;

    if hi < 0 then
    begin
      Result := false;
      exit;
    end;
  end;

  Result := lo = 0;
end;

function GetBellNumber(n: integer): integer;
begin
  var bell := new integer[n + 1, n + 1];
  bell[0, 0] := 1;

  for var i := 1 to n do
  begin
    bell[i, 0] := bell[i - 1, i - 1];
    for var j := 1 to i do
      bell[i, j] := bell[i - 1, j - 1] + bell[i, j - 1];
  end;

  Result := bell[n, 0];
end;

function SearchRotate(nums: array of integer; target: integer): integer;
  function FindPivot: integer;
  begin
    var start := 0;
    var &end := nums.Length - 1;
    while start < &end do
    begin
      var mid := (start + &end) div 2;
      if nums[mid] > nums[&end] then
        start := mid + 1
      else
        &end := mid;
    end;
    Result := start;
  end;

  function BinarySearch(left, right: integer): integer;
  begin
    while left <= right do
    begin
      var mid := (left + right) div 2;
      if nums[mid] = target then
        exit(mid)
      else if nums[mid] < target then
        left := mid + 1
      else
        right := mid - 1;
    end;
    Result := -1;
  end;
begin
  if nums.Length = 0 then
  begin
    Result := -1;
    exit;
  end;

  var pivot := FindPivot;

  if (pivot > 0) and (target >= nums[0]) and (target <= nums[pivot - 1]) then
    Result := BinarySearch(0, pivot - 1)
  else
    Result := BinarySearch(pivot, nums.Length - 1);
end;

function IsValidParentheses(s: string): boolean;
begin
  var stack := new Stack<char>;
  var parenthesesMap := Dict(')' to '(', ']' to '[', '}' to '{');

  foreach var ch in s do
  begin
    if (ch = '(') or (ch = '[') or (ch = '{') then
      stack.Push(ch)
    else if (ch = ')') or (ch = ']') or (ch = '}') then
    begin
      if (stack.Count = 0) or (stack.Pop <> parenthesesMap[ch]) then
      begin
        Result := false;
        exit;
      end;
    end
    else
    begin
      Result := false;
      exit;
    end;
  end;

  Result := stack.Count = 0;
end;

function ReplaceGreatest(arr: array of integer): array of integer;
begin
  var replaced := arr.Copy;
  var maxRight := -1;

  for var i := replaced.Length - 1 downto 0 do
  begin
    var temp := replaced[i];
    replaced[i] := maxRight;
    if temp > maxRight then
      maxRight := temp;
  end;

  Result := replaced;
end;

function MakeNumberBeautiful(n: integer; target: integer): integer;
  function DigitSum(number: integer): integer;
  begin
    var sum := 0;
    var num := number;
    while num > 0 do
    begin
      sum += num mod 10;
      num := num div 10;
    end;
    Result := sum;
  end;
begin
  var lst := 1;
  var add := 0;

  while DigitSum(n + add) > target do
  begin
    var x := Round(Power(10, lst));
    add := x - (n mod x);
    lst += 1;
  end;

  Result := add;
end;

function FibMemoization(n: integer; memo: Dictionary<integer, integer> := nil): integer;
begin
  if memo = nil then
    memo := new Dictionary<integer, integer>;

  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 1
  else if memo.ContainsKey(n) then
    Result := memo[n]
  else
  begin
    var fibVal := FibMemoization(n - 1, memo) + FibMemoization(n - 2, memo);
    memo[n] := fibVal;
    Result := fibVal;
  end;
end;

function LongestAlternatingSubsequence(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var increasing := ArrGen(nums.Length, i -> 1);
  var decreasing := ArrGen(nums.Length, i -> 1);

  for var i := 1 to nums.Length - 1 do
    for var j := 0 to i - 1 do
    begin
      if nums[i] > nums[j] then
        increasing[i] := max(increasing[i], decreasing[j] + 1);
      if nums[i] < nums[j] then
        decreasing[i] := max(decreasing[i], increasing[j] + 1);
    end;

  Result := max(increasing.Max, decreasing.Max);
end;

function FindReplaceString(s: string; indices: array of integer; sources, targets: array of string): string;
begin
  var operations := new List<(integer, string, string)>;
  for var i := 0 to indices.Length - 1 do
    operations.Add((indices[i], sources[i], targets[i]));

  operations := operations.OrderBy(x -> x.Item1).ToList;

  var ptr := 0;
  var ret := new StringBuilder;

  foreach var op in operations do
  begin
    var (idx, source, target) := op;
    ret.Append(s.Substring(ptr, idx - ptr));

    if s.Substring(idx, source.Length) = source then
      ret.Append(target)
    else
      ret.Append(s.Substring(idx, source.Length));

    ptr := idx + source.Length;
  end;

  if ptr < s.Length then
    ret.Append(s.Substring(ptr));

  Result := ret.ToString;
end;

function ValidMountainArray(arr: array of integer): boolean;
begin
  if arr.Length < 3 then
  begin
    Result := false;
    exit;
  end;

  var peak := 0;
  for var i := 1 to arr.Length - 1 do
    if arr[i] > arr[i - 1] then
      peak := i
    else
      break;

  if (peak = 0) or (peak = arr.Length - 1) then
  begin
    Result := false;
    exit;
  end;

  for var i := peak to arr.Length - 2 do
    if arr[i] <= arr[i + 1] then
    begin
      Result := false;
      exit;
    end;

  Result := true;
end;

