  if s.Length <> 5 then begin Result := False; exit; end;
  if s[2] <> ':' then begin Result := False; exit; end;
  if (s[0] < '0') or (s[0] > '9') or (s[1] < '0') or (s[1] > '9') then begin Result := False; exit; end;
  if (s[3] < '0') or (s[3] > '9') or (s[4] < '0') or (s[4] > '9') then begin Result := False; exit; end;
  var hh := integer(s[0]) - integer('0');
  hh := hh * 10 + (integer(s[1]) - integer('0'));
  var mm := integer(s[3]) - integer('0');
  mm := mm * 10 + (integer(s[4]) - integer('0'));
  Result := (hh >= 0) and (hh <= 23) and (mm >= 0) and (mm <= 59);
end;

